window.__vaultPreview("b2b557be2ca18754",{"text":"/* COLOR SYSTEM\n   Forest and gold: deep forest green with a warm gold accent on warm white.\n   One theme only. Bright gold #C9A24A is for fills, dots and anything on the\n   green nav; gold text on light surfaces uses the deeper #8A6A1F so it reads. */\n:root {\n  --nav-glass: rgba(29, 58, 46, 0.97);\n  --nav-ink: #f7f5ef;\n  --spark: #c9a24a;\n  --spark-ink: #8a6a1f;\n  --paper: #ffffff;\n\n  --brand: #1d3a2e;\n  --brand-strong: #132a21;\n  --ink: #132a21;\n\n  --bg: #f7f5ef;\n  --surface: #ffffff;\n  --surface-2: #f0ede3;\n  --border: #e5e0d2;\n  --text: #132a21;\n  --muted: #6b6a5e;\n  --accent: var(--brand);\n  --highlight: var(--spark-ink);\n  --gradient: linear-gradient(155deg, #2c5242 0%, #1d3a2e 55%, #132a21 100%);\n  --shadow-sm: 0 1px 2px rgba(19, 42, 33, 0.06), 0 10px 24px -14px rgba(19, 42, 33, 0.2);\n  --shadow-md: 0 2px 4px rgba(19, 42, 33, 0.06), 0 20px 38px -16px rgba(19, 42, 33, 0.28);\n  --dots: none;\n\n  /* Older names still used around the stylesheet */\n  --soft: var(--bg);\n  --white: var(--surface);\n  --shadow: var(--shadow-sm);\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  font-family: \"Inter\", Arial, sans-serif;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  min-height: 100vh;\n  margin: 0;\n  overflow-x: hidden;\n  background: var(--soft);\n  color: var(--text);\n  font-family: \"Inter\", Arial, sans-serif;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\nimg {\n  max-width: 100%;\n  display: block;\n}\n\n.dashboard-layout{\n  min-height: 100vh;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  background: var(--dots), var(--bg);\n}\n\n.dashboard-main{\n  min-width: 0;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  align-content: start;\n  gap: 18px;\n  padding: 22px;\n}\n\n/* SHARED CARDS */\n.home-hero,\n.tools-panel{\n  border: 0;\n  border-radius: 8px;\n  background: var(--surface);\n  color: var(--text);\n  box-shadow: var(--shadow-sm);\n}\n\n/* HOME */\n.home-hero {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  padding: 48px;\n}\n\n.home-hero h1 {\n  max-width: 620px;\n  margin: 0 0 18px;\n  font-size: clamp(2.1rem, 3.2vw, 3.1rem);\n  font-weight: 700;\n  line-height: 1.15;\n}\n\n.home-hero .description {\n  max-width: 560px;\n  margin: 0 0 28px;\n  font-size: 1.05rem;\n}\n\n/* Secondary button: a soft tint rather than an outline, so no stray hairlines */\n.button-outline,\n.home-page .button-outline {\n  border: 0;\n  background: rgba(19, 42, 33, 0.1) !important;\n  color: var(--accent) !important;\n}\n\n.button-outline:hover,\n.home-page .button-outline:hover {\n  background: rgba(19, 42, 33, 0.18) !important;\n  color: var(--accent) !important;\n}\n\nh1 {\n  margin: 0 0 24px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: clamp(2.5rem, 4vw, 4.7rem);\n  font-weight: 700;\n  line-height: 1.12;\n}\n\nh1,\nh2,\nh3 {\n  color: var(--text);\n}\n\nh1 span{\n  color: var(--highlight);\n  font-weight: 800;\n}\n\n.description{\n  color: var(--muted);\n  line-height: 1.7;\n}\n\n.description {\n  max-width: 680px;\n  margin: 0 0 30px;\n  font-size: 1.08rem;\n}\n\n.button{\n  min-height: 44px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0 20px;\n  border-radius: 8px;\n  background: var(--brand);\n  color: #ffffff;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-weight: 800;\n  transition: background 0.2s ease;\n}\n\n.button:hover{\n  background: var(--brand-strong);\n  color: #ffffff;\n}\n\n@keyframes toolsRun {\n  from {\n    transform: translateX(0);\n  }\n\n  to {\n    transform: translateX(-50%);\n  }\n}\n\n.section-label {\n  margin: 0 0 12px;\n  color: var(--accent);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-weight: 800;\n}\n\n@keyframes colonBlink {\n  50% {\n    opacity: 0.2;\n  }\n}\n\n/* Live status: working now, or a countdown to the next shift */\n.hours-status {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.88rem;\n}\n\n.status-dot {\n  width: 9px;\n  height: 9px;\n  flex: none;\n  border-radius: 50%;\n  background: var(--muted);\n}\n\n.hours-status.is-online {\n  color: var(--text);\n}\n\n.hours-status.is-online .status-dot {\n  background: #c9a24a;\n  box-shadow: 0 0 0 0 rgba(201, 162, 74, 0.6);\n  animation: statusPulse 1.8s ease-out infinite;\n}\n\n@keyframes statusPulse {\n  to {\n    box-shadow: 0 0 0 8px rgba(201, 162, 74, 0);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  \n  .hours-status.is-online .status-dot {\n    animation: none;\n  }\n}\n\n/* RESPONSIVE */\n@media (max-width: 1100px) {\n  .home-hero{\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 800px) {\n\n  .home-hero{\n    padding: 26px;\n  }\n}\n\n@media (max-width: 600px) {\n  .dashboard-main{\n    gap: 14px;\n    padding: 12px 12px 84px;\n  }\n\n  h1 {\n    font-size: 2.35rem;\n  }\n\n  .button {\n    width: 100%;\n  }\n}\n\n/* HOME */\n.home-page {\n  background: var(--dots), var(--bg);\n}\n\n/* CONTACT PAGE (GOOGLE ACCOUNT STYLE) */\n.contact-page {\n  --g-bg: var(--bg);\n  --g-surface: var(--surface);\n  --g-text: var(--text);\n  --g-muted: var(--muted);\n  --g-outline: #a3a08f;\n  --g-divider: var(--border);\n  --g-hover: rgba(19, 42, 33, 0.08);\n  --g-accent: var(--brand);\n  --g-primary-bg: var(--brand);\n  --g-primary-text: #ffffff;\n}\n\n.contact-page{\n  background: var(--dots), var(--g-bg) !important;\n}\n\n.contact-avatar-ring {\n  width: 112px;\n  height: 112px;\n  margin-bottom: 18px;\n  padding: 4px;\n  border-radius: 50%;\n  background: var(--brand);\n}\n\n.contact-avatar-ring img {\n  width: 100%;\n  height: 100%;\n  padding-top: 8px;\n  border: 4px solid var(--g-bg);\n  border-radius: 50%;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n/* HOME: VISION STATEMENT + NUMBERED SERVICES */\n\n/* Vision: a bold statement card carrying the palette gradient */\n.vision-block {\n  padding: 48px 48px 36px;\n  border: 0;\n  border-radius: 20px;\n  background:\n    radial-gradient(circle, rgba(255, 255, 255, 0.07) 1px, transparent 1.5px) 0 0 / 20px 20px,\n    var(--gradient);\n  color: #ffffff;\n  box-shadow: var(--shadow-md);\n}\n\n.vision-eyebrow {\n  display: block;\n  margin: 0 0 18px;\n  color: #e8cf8f;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.8rem;\n  font-weight: 800;\n  letter-spacing: 0.16em;\n  text-transform: uppercase;\n}\n\n.vision-block h2{\n  max-width: 860px;\n  margin: 0;\n  color: #ffffff;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: clamp(1.9rem, 3.6vw, 3.1rem);\n  font-weight: 700;\n  line-height: 1.12;\n  letter-spacing: -0.02em;\n}\n\n.vision-block h2 em {\n  color: #e8cf8f;\n  font-style: normal;\n}\n\n.vision-foot {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 20px;\n  margin-top: 34px;\n  padding-top: 24px;\n}\n\n.vision-points {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px 26px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.vision-points li {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  color: rgba(255, 255, 255, 0.88);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-weight: 600;\n}\n\n.vision-points li::before {\n  content: \"\";\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--spark);\n}\n\n.vision-cta {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 46px;\n  padding: 0 26px;\n  border-radius: 999px;\n  background: var(--spark);\n  color: var(--ink);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-weight: 800;\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), 0 10px 22px -8px rgba(201, 162, 74, 0.6);\n  transition: background 0.2s ease, transform 0.2s ease;\n}\n\n.vision-cta:hover {\n  background: #c9a24a;\n  color: var(--ink);\n  transform: translateY(-2px);\n}\n\n.vision-cta span {\n  transition: transform 0.2s ease;\n}\n\n.vision-cta:hover span {\n  transform: translateX(3px);\n}\n\n/* Services: a numbered list with column dividers instead of icon cards */\n.services-block {\n  padding: 40px 48px 12px;\n  border: 0;\n  border-radius: 20px;\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n}\n\n.services-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 16px 24px;\n  margin-bottom: 28px;\n}\n\n.services-head .section-label {\n  margin: 0 0 6px;\n  font-size: 0.8rem;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n}\n\n.services-head h2 {\n  margin: 0;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: clamp(1.6rem, 2.6vw, 2.2rem);\n  font-weight: 700;\n  letter-spacing: -0.01em;\n}\n\n.services-list {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.services-list li {\n  position: relative;\n  padding: 28px 24px 30px;\n}\n\n.services-list li:first-child {\n  padding-left: 0;\n  border-left: 0;\n}\n\n/* Accent bar that grows across the top on hover */\n.services-list li::before {\n  content: \"\";\n  position: absolute;\n  top: -1px;\n  left: 0;\n  width: 0;\n  height: 3px;\n  background: var(--accent);\n  transition: width 0.3s ease;\n}\n\n.services-list li:hover::before {\n  width: 100%;\n}\n\n.svc-no {\n  display: block;\n  margin-bottom: 18px;\n  color: transparent;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 2.6rem;\n  font-weight: 800;\n  line-height: 1;\n  -webkit-text-stroke: 1.5px var(--highlight);\n}\n\n.services-list h3 {\n  margin: 0 0 8px;\n  color: var(--text);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.1rem;\n  font-weight: 700;\n}\n\n.services-list p {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.92rem;\n  line-height: 1.55;\n}\n\n/* Fade in on scroll (only when JS is running) */\n.js-ready .reveal {\n  transition: opacity 0.6s ease, transform 0.6s ease;\n}\n\n.js-ready .reveal:not(.is-visible) {\n  opacity: 0;\n  transform: translateY(20px);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .js-ready .reveal,\n  .js-ready .reveal:not(.is-visible) {\n    opacity: 1;\n    transform: none;\n    transition: none;\n  }\n}\n\n@media (max-width: 1100px) {\n  .services-list {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .services-list li:nth-child(odd) {\n    padding-left: 0;\n    border-left: 0;\n  }\n\n  .services-list li:nth-child(n + 3) {\n  }\n}\n\n@media (max-width: 600px) {\n  .vision-block,\n  .services-block {\n    padding: 30px 22px;\n  }\n\n  .services-list {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .services-list li {\n    padding: 24px 0;\n    border-left: 0;\n  }\n\n  .services-list li + li {\n  }\n}\n\n/* Cover photo banner (like a LinkedIn or OLJ cover) */\n/* Capped at 440px tall. The crop is anchored 30% down the image so the\n   VENUS wordmark near the top stays in frame and the trim comes mostly\n   off the bottom of the desk scene. */\n.profile-banner {\n  aspect-ratio: 3 / 1;\n  max-height: 440px;\n  overflow: hidden;\n  background: var(--brand-strong);\n}\n\n.profile-banner img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: 50% 30%;\n}\n\n.home-hero .profile-main h1 {\n  max-width: 680px;\n  margin: 0 0 16px;\n  font-size: clamp(1.8rem, 2.8vw, 2.5rem);\n  line-height: 1.2;\n}\n\n.profile-body {\n  display: grid;\n  grid-template-columns: 200px minmax(0, 1fr);\n  gap: 40px;\n  padding: 0 48px 40px;\n}\n\n.profile-side {\n  display: grid;\n  justify-items: center;\n  align-content: start;\n  gap: 22px;\n}\n\n.profile-photo {\n  width: 184px;\n  height: 184px;\n  margin-top: -120px;\n  padding-top: 14px;\n  border: 5px solid var(--surface);\n  border-radius: 50%;\n  background: linear-gradient(160deg, #f0ede3, #e5e0d2);\n  object-fit: cover;\n  object-position: 50% 0;\n  box-shadow: var(--shadow-md);\n}\n\n/* Stats summary under the photo in the Home overview */\n.hero-stats {\n  width: 100%;\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  margin: 0;\n  padding: 12px 6px;\n  border: 0;\n  border-radius: 14px;\n  background: var(--surface);\n  box-shadow: var(--shadow-sm);\n  list-style: none;\n  text-align: center;\n}\n\n.hero-stats strong {\n  display: block;\n  color: var(--highlight);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.35rem;\n  font-weight: 800;\n  line-height: 1.1;\n}\n\n.hero-stats span {\n  color: var(--muted);\n  font-size: 0.74rem;\n}\n\n.profile-actions {\n  width: 100%;\n  display: grid;\n  gap: 10px;\n}\n\n.profile-actions .button {\n  width: 100%;\n  border-radius: 999px;\n}\n\n.profile-main {\n  padding-top: 26px;\n}\n\n.profile-main .description,\n.home-hero .profile-main .description {\n  max-width: 640px;\n  margin: 0 0 24px;\n}\n\n.skill-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin: 0 0 26px;\n  padding: 0;\n  list-style: none;\n}\n\n.skill-chips li {\n  padding: 6px 14px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 0.9rem;\n}\n\n@media (max-width: 800px) {\n  .profile-banner {\n    aspect-ratio: 3 / 2;\n  }\n\n  .profile-body {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 0;\n    padding: 0 22px 28px;\n  }\n\n  .profile-photo {\n    width: 150px;\n    height: 150px;\n    margin-top: -80px;\n  }\n\n  .hero-stats,\n  .profile-actions {\n    max-width: 320px;\n  }\n}\n\n.graphic-preview {\n  width: 100%;\n  display: block;\n  aspect-ratio: 16 / 10;\n  padding: 0;\n  overflow: hidden;\n  border: 0;\n  border-radius: 8px;\n  background: var(--surface-2);\n  cursor: zoom-in;\n}\n\n.graphic-preview img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  transition: transform 0.35s ease;\n}\n\n.graphic-preview:hover img {\n  transform: scale(1.03);\n}\n\n.graphic-preview:focus-visible {\n  outline: 3px solid var(--accent);\n  outline-offset: 2px;\n}\n\n/* Enlarged view */\n.lightbox {\n  width: min(1200px, 94vw);\n  max-height: 92vh;\n  padding: 0;\n  overflow: visible;\n  border: 0;\n  background: transparent;\n}\n\n.lightbox::backdrop {\n  background: rgba(0, 0, 0, 0.85);\n}\n\n.lightbox img {\n  width: 100%;\n  max-height: 92vh;\n  object-fit: contain;\n  border-radius: 10px;\n  background: #ffffff;\n}\n\n.lightbox-close {\n  position: absolute;\n  top: -14px;\n  right: -14px;\n  width: 38px;\n  height: 38px;\n  border: 0;\n  border-radius: 50%;\n  background: #ffffff;\n  color: var(--ink);\n  font-size: 1.5rem;\n  line-height: 1;\n  cursor: pointer;\n  box-shadow: var(--shadow-md);\n}\n\n.lightbox-close:hover {\n  background: var(--spark);\n}\n\n@media (max-width: 600px) {\n  .lightbox-close {\n    top: 6px;\n    right: 6px;\n  }\n}\n\n/* HOME: EVERYTHING ON ONE SHEET (no separate boxes, thin dividers between sections) */\n/* TYPOGRAPHY: Inter for everything (set on body).\n   !important is used so this wins over the older per-component heading fonts. */\nh1,\nh3,\n.hero-stats strong,\n.svc-no {\n  font-family: \"Inter\", Arial, sans-serif !important;\n  letter-spacing: -0.01em;\n}\n\nh1{\n  font-weight: 700 !important;\n}\n\nh3 {\n  font-weight: 600 !important;\n}\n\n/* HOME: brands I've worked with (white tiles so every logo reads in both themes) */\n\n.page-summaries {\n  padding: 32px 48px;\n}\n\n@media (max-width: 600px) {\n  \n  .page-summaries {\n    padding: 26px 22px;\n  }\n}\n\n/* ===========================================================\n   TOP BAR + CURVED DOCK\n   Replaces the old left sidebar. The dock is a floating bar\n   whose top edge dips into a notch; the active page's icon\n   rides up into that notch, and the notch slides across on\n   hover or keyboard focus.\n   =========================================================== */\n\n.dashboard-layout{\n  grid-template-rows: auto minmax(0, 1fr);\n}\n\n.dashboard-main{\n  padding-bottom: 130px;\n}\n\n/* --- Top bar ---\n   Dark smoked glass to match the dock, in both themes. Everything inside is\n   therefore light-on-dark regardless of the light/dark setting. */\n.topbar {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 10px 22px;\n  background: var(--nav-glass);\n  backdrop-filter: blur(22px) saturate(160%);\n  -webkit-backdrop-filter: blur(22px) saturate(160%);\n  color: var(--paper);\n  font-family: \"Inter\", Arial, sans-serif;\n}\n\n.topbar-logo {\n  display: inline-flex;\n  align-items: center;\n  padding: 4px 6px;\n  border-radius: 12px;\n  transition: background 0.2s ease;\n}\n\n.topbar-logo:hover,\n.topbar-socials a:hover,\n.topbar-me:hover {\n  background: rgba(255, 255, 255, 0.14);\n}\n\n.topbar-logo img {\n  width: 138px;\n  height: auto;\n}\n\n/* The bar is dark in both themes, so the white wordmark is always the one shown */\n.topbar-logo .logo-full {\n  display: none;\n}\n\n.topbar-logo .logo-full-dark{\n  display: block;\n}\n\n.topbar-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.topbar-socials {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n}\n\n.topbar-socials a {\n  display: inline-flex;\n  padding: 7px;\n  border-radius: 999px;\n  transition: background 0.2s ease;\n}\n\n.topbar-socials img {\n  width: 22px;\n  height: 22px;\n  object-fit: contain;\n}\n\n.topbar-me {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  padding: 5px 12px 5px 5px;\n  border-radius: 999px;\n  transition: background 0.2s ease;\n}\n\n/* Venus.png is a cutout: a pale disc sits behind it, and the top padding\n   crops the ragged bottom edge of the cutout out of the circle */\n.topbar-avatar {\n  width: 34px;\n  height: 34px;\n  padding-top: 3px;\n  border-radius: 999px;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n.topbar-me-text {\n  display: flex;\n  flex-direction: column;\n  line-height: 1.25;\n}\n\n.topbar-me-text strong {\n  color: var(--paper);\n  font-size: 0.86rem;\n  font-weight: 600;\n}\n\n.topbar-me-text small {\n  color: rgba(255, 255, 255, 0.7);\n  font-size: 0.72rem;\n}\n/* --- Curved dock ---\n   The bar is a frosted pane clipped to a path the script regenerates as the\n   notch moves, so there is no outline anywhere on it. Only the bubble behind\n   the lifted icon changes colour: the icon artwork itself is never recoloured. */\n.dock {\n  position: fixed;\n  bottom: 16px;\n  left: 50%;\n  z-index: 60;\n  width: min(560px, calc(100% - 28px));\n  height: 72px;\n  transform: translateX(-50%);\n  font-family: \"Inter\", Arial, sans-serif;\n}\n\n/* Dark glass: a smoked pane in both themes, so the dock reads as one object\n   against the light page rather than melting into it */\n.dock-glass {\n  position: absolute;\n  inset: 0;\n  background: var(--nav-glass);\n  backdrop-filter: blur(22px) saturate(160%);\n  -webkit-backdrop-filter: blur(22px) saturate(160%);\n  box-shadow: 0 16px 38px -14px rgba(0, 0, 0, 0.6);\n  border-radius: 24px;\n}\n\n.dock-bubble {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 54px;\n  height: 54px;\n  border-radius: 999px;\n  background: var(--spark);\n  box-shadow: 0 6px 16px -6px rgba(201, 162, 74, 0.9);\n  transform: translate(-100px, -23px);\n  pointer-events: none;\n}\n\n.dock-items {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  height: 100%;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.dock-items li {\n  flex: 1;\n  min-width: 0;\n}\n\n.dock-item {\n  display: flex;\n  height: 100%;\n  flex-direction: column;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 3px;\n  padding-top: 18px;\n  color: rgba(255, 255, 255, 0.72);\n  text-align: center;\n}\n\n.dock-icon {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 25px;\n  height: 25px;\n  transition: transform 0.28s cubic-bezier(0.34, 1.3, 0.64, 1);\n}\n\n.dock-icon img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n}\n\n.dock-label {\n  font-size: 0.67rem;\n  font-weight: 500;\n  letter-spacing: 0.01em;\n  transition: color 0.2s ease;\n}\n\n.dock-item:hover .dock-label {\n  color: var(--paper);\n}\n\n/* The item under the notch: the icon lifts into the bubble and keeps its own\n   colours, so the artwork stays readable instead of turning into a silhouette */\n.dock-item.dipped .dock-icon {\n  transform: translateY(-26px);\n}\n\n.dock-item.dipped .dock-label {\n  color: var(--spark);\n  font-weight: 700;\n}\n\n.dock-item:focus-visible {\n  outline: 2px solid var(--spark);\n  outline-offset: -4px;\n  border-radius: 14px;\n}\n\n@media (max-width: 480px) {\n  .dock {\n    height: 66px;\n    bottom: 12px;\n  }\n\n  .dock-label {\n    font-size: 0.6rem;\n  }\n\n  .dock-icon {\n    width: 22px;\n    height: 22px;\n  }\n\n  .topbar {\n    padding: 8px 14px;\n  }\n\n  .topbar-logo img {\n    width: 112px;\n  }\n\n  .topbar-me-text {\n    display: none;\n  }\n\n  .topbar-me {\n    padding: 5px;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .dock-icon {\n    transition: none;\n  }\n}\n\n/* --- Tools panel: grouped by category, using the folder icons --- */\n.tools-panel {\n  padding: 28px 32px 30px;\n}\n\n.tools-panel-title {\n  margin: 0 0 22px;\n  color: var(--accent);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.12rem;\n  font-weight: 800;\n  letter-spacing: 0.02em;\n}\n\n.tools-groups {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 30px 36px;\n}\n\n.tools-group-head {\n  display: flex;\n  align-items: center;\n  gap: 11px;\n  margin-bottom: 10px;\n}\n\n.tools-group-head img {\n  width: 32px;\n  height: 32px;\n  flex: none;\n  object-fit: contain;\n}\n\n.tools-group-head h3 {\n  margin: 0;\n  color: var(--text);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1rem;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n}\n\n/* The logo PNGs are square with generous transparent margins, so a tight gap\n   still reads as well spaced */\n.tools-group-logos {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px 10px;\n}\n\n/* Each logo sits on its own tile. Hover changes the tile behind it only,\n   so the logo artwork keeps its real colours. */\n@media (max-width: 600px) {\n  .tools-panel {\n    padding: 22px 20px 24px;\n  }\n\n  .tools-groups {\n    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n    gap: 22px;\n  }\n\n  .tools-group-logos img {\n    width: 78px;\n    height: 78px;\n  }\n}\n\n/* ===========================================================\n   ABOUT PAGE — BENTO LAYOUT\n   A grid of self-contained cards. Separation comes from the gaps\n   and the card shadows, so there are no divider rules anywhere.\n   =========================================================== */\n\n.about-page-main {\n  gap: 20px;\n}\n\n.bento-title {\n  padding: 14px 0 2px;\n  text-align: center;\n}\n\n.bento-title h1 {\n  margin: 0 0 6px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: clamp(2.1rem, 4.4vw, 3.4rem);\n  font-weight: 700;\n  letter-spacing: -0.01em;\n  color: var(--text);\n}\n\n.bento-title p {\n  margin: 0;\n  color: var(--muted);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.9rem;\n  letter-spacing: 0.04em;\n}\n\n.bento-title p span {\n  margin: 0 6px;\n  color: var(--spark);\n}\n\n.bento {\n  display: grid;\n  grid-template-columns: minmax(0, 330px) minmax(0, 1fr);\n  gap: 16px;\n  align-items: start;\n}\n\n/* minmax(0,1fr) keeps the marquee track from sizing this column to its own\n   max-content width, which would blow the whole grid past the viewport */\n.bento-col {\n  min-width: 0;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  gap: 16px;\n  align-content: start;\n}\n\n.bento-card {\n  min-width: 0;\n  padding: 24px 26px;\n  border: 0;\n  border-radius: 18px;\n  background: var(--surface);\n  color: var(--text);\n  box-shadow: var(--shadow-sm);\n}\n\n.bento-card-title {\n  margin: 0 0 16px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.05rem;\n  font-weight: 600;\n  color: inherit;\n}\n\n/* Photo */\n.bento-photo {\n  padding: 0;\n  overflow: hidden;\n  line-height: 0;\n}\n\n.bento-photo img {\n  width: 100%;\n  aspect-ratio: 4 / 5;\n  object-fit: cover;\n  object-position: center top;\n}\n\n/* Greeting card: the accent block from the reference, in gold */\n.bento-hello {\n  background: var(--spark);\n  color: var(--brand-strong);\n}\n\n.bento-hello h2 {\n  margin: 0 0 10px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.5rem;\n  font-weight: 700;\n  color: var(--brand-strong);\n}\n\n.bento-hello h2 strong {\n  font-weight: 700;\n}\n\n.bento-quote {\n  margin: 0;\n  font-size: 0.94rem;\n  line-height: 1.6;\n  color: var(--brand-strong);\n}\n\n/* Education — the graduation photo sits behind a scrim so the text stays legible */\n.bento-education {\n  position: relative;\n  overflow: hidden;\n  background: var(--brand-strong);\n  color: #ffffff;\n}\n\n.bento-education-bg {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.bento-education::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(175deg, rgba(0, 0, 0, 0.62) 0%, rgba(0, 0, 0, 0.93) 62%, rgba(0, 0, 0, 0.97) 100%);\n}\n\n.bento-education-body {\n  position: relative;\n  z-index: 1;\n}\n\n.bento-school {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.bento-school-logo {\n  width: 46px;\n  height: 46px;\n  flex: none;\n  object-fit: contain;\n}\n\n.bento-school div {\n  display: grid;\n  gap: 3px;\n}\n\n.bento-school strong {\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.98rem;\n  font-weight: 600;\n}\n\n.bento-school span {\n  font-size: 0.84rem;\n  color: #e5e0d2;\n}\n\n.bento-skills .skill-chips {\n  margin: 0 0 20px;\n}\n\n.bento-skills .skill-chips:last-child {\n  margin-bottom: 0;\n}\n\n.bento-skills .skill-chips li {\n  font-size: 0.82rem;\n  padding: 5px 12px;\n}\n\n/* Featured work — the dark panel from the reference */\n.bento-work {\n  background: var(--brand-strong);\n  color: #ffffff;\n}\n\n.bento-work-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 18px;\n}\n\n.bento-work-head .bento-card-title {\n  margin: 0;\n}\n\n/* Black by default so it reads on a white card; gold inside the dark panel */\n.bento-link {\n  color: var(--accent);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.88rem;\n  font-weight: 600;\n  white-space: nowrap;\n  transition: opacity 0.2s ease;\n}\n\n.bento-link:hover {\n  opacity: 0.75;\n}\n\n.bento-work-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));\n  gap: 14px;\n}\n\n.bento-work-item {\n  display: block;\n  padding: 10px;\n  border-radius: 14px;\n  background: rgba(255, 255, 255, 0.07);\n  transition: background 0.22s ease, transform 0.22s ease;\n}\n\n.bento-work-item:hover {\n  background: rgba(201, 162, 74, 0.18);\n  transform: translateY(-3px);\n}\n\n.bento-work-item img {\n  width: 100%;\n  aspect-ratio: 16 / 11;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 9px;\n}\n\n.bento-work-label {\n  display: grid;\n  gap: 2px;\n  padding: 10px 4px 2px;\n}\n\n.bento-work-label strong {\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.88rem;\n  font-weight: 600;\n}\n\n.bento-work-label small {\n  font-size: 0.76rem;\n  color: #e5e0d2;\n}\n\n/* Tools — tiles again, so hover only changes what sits behind the logo */\n/* Travel carousel */\n.travel-nav {\n  position: absolute;\n  top: 50%;\n  width: 34px;\n  height: 34px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  border: 0;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.82);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n  color: var(--brand-strong);\n  cursor: pointer;\n  transform: translateY(-50%);\n  transition: background 0.2s ease;\n}\n\n.travel-nav:hover {\n  background: var(--spark);\n}\n\n.travel-prev {\n  left: 10px;\n}\n\n.travel-next {\n  right: 10px;\n}\n\n.travel-nav svg {\n  width: 18px;\n  height: 18px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 2.2;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.travel-dots {\n  display: flex;\n  justify-content: center;\n  gap: 7px;\n  margin-top: 22px;\n}\n\n.travel-dots button {\n  width: 8px;\n  height: 8px;\n  padding: 0;\n  border: 0;\n  border-radius: 999px;\n  background: var(--surface-2);\n  cursor: pointer;\n  transition: background 0.2s ease, width 0.2s ease;\n}\n\n.travel-dots button.active {\n  width: 20px;\n  background: var(--spark);\n}\n\n@media (max-width: 980px) {\n  .bento {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n@media (max-width: 600px) {\n  .bento-card {\n    padding: 20px 18px;\n  }\n\n  .bento-work-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n/* --- How I Work card --- */\n.how-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n  gap: 20px;\n}\n\n.how-item {\n  display: grid;\n  gap: 8px;\n  align-content: start;\n}\n\n.how-icon {\n  width: 46px;\n  height: 46px;\n  display: grid;\n  place-items: center;\n  border-radius: 14px;\n  background: rgba(19, 42, 33, 0.1);\n  color: var(--accent);\n}\n\n.how-icon svg {\n  width: 24px;\n  height: 24px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.how-item h3 {\n  margin: 4px 0 0;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.98rem;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.how-item p {\n  margin: 0;\n  font-size: 0.88rem;\n  line-height: 1.62;\n  color: var(--muted);\n}\n\n/* --- Travel coverflow ---\n   Cards sit on a 3D stage: the active one faces front, its neighbours sit\n   behind and turned. Photos are letterboxed with object-fit: contain so the\n   whole picture is visible and nothing is cropped. */\n.travel-carousel {\n  min-width: 0;\n  position: relative;\n  padding: 18px 0 6px;\n}\n\n.travel-stage {\n  position: relative;\n  height: clamp(300px, 40vw, 480px);\n  perspective: 1500px;\n  transform-style: preserve-3d;\n}\n\n.travel-slide {\n  position: absolute;\n  top: 0;\n  left: 50%;\n  width: min(58%, 500px);\n  height: 100%;\n  margin: 0;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  background: transparent;\n  opacity: 0;\n  transform: translateX(-50%) scale(0.62);\n  transition: transform 0.65s cubic-bezier(0.22, 0.8, 0.26, 1), opacity 0.55s ease;\n  pointer-events: none;\n  z-index: 1;\n}\n\n/* The photos carry their own frame and shadow, so nothing is added here */\n.travel-slide img {\n  max-width: 100%;\n  max-height: 100%;\n  width: auto;\n  height: auto;\n  object-fit: contain;\n  display: block;\n}\n\n.travel-slide.is-prev {\n  opacity: 0.55;\n  transform: translateX(-102%) scale(0.78) rotateY(17deg);\n  z-index: 2;\n}\n\n.travel-slide.is-next {\n  opacity: 0.55;\n  transform: translateX(2%) scale(0.78) rotateY(-17deg);\n  z-index: 2;\n}\n\n.travel-slide.is-active {\n  opacity: 1;\n  transform: translateX(-50%) scale(1) rotateY(0deg);\n  pointer-events: auto;\n  z-index: 3;\n}\n\n.travel-nav {\n  z-index: 5;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .travel-slide {\n    transition: opacity 0.2s ease;\n  }\n}\n\n@media (max-width: 600px) {\n  .travel-slide {\n    width: min(76%, 340px);\n  }\n\n  .travel-slide.is-prev {\n    transform: translateX(-110%) scale(0.72) rotateY(18deg);\n  }\n\n  .travel-slide.is-next {\n    transform: translateX(10%) scale(0.72) rotateY(-18deg);\n  }\n}\n\n/* --- Tool logos: embossed, running --- */\n.bento-tool-marquee {\n  min-width: 0;\n  width: 100%;\n  overflow: hidden;\n  -webkit-mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);\n  mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);\n}\n\n.bento-tool-track {\n  width: max-content;\n  display: flex;\n  align-items: center;\n  gap: 40px;\n  padding-right: 40px;\n  animation: toolsRun 38s linear infinite;\n}\n\n.bento-tool-marquee:hover .bento-tool-track,\n.bento-tool-marquee:focus-within .bento-tool-track {\n  animation-play-state: paused;\n}\n\n.bento-tool-track img,\n.tools-group-logos img {\n  object-fit: contain;\n  transition: transform 0.22s ease;\n}\n\n.bento-tool-track img {\n  width: 88px;\n  height: 88px;\n  flex: none;\n}\n\n.tools-group-logos img {\n  width: 100px;\n  height: 100px;\n}\n\n.bento-tool-track img:hover,\n.tools-group-logos img:hover {\n  transform: translateY(-4px) scale(1.06);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .bento-tool-track {\n    animation: none;\n  }\n}\n\n@media (max-width: 600px) {\n  .bento-tool-track img {\n    width: 68px;\n    height: 68px;\n  }\n}\n\n/* Side cards are clickable: clicking one brings it to the front */\n.travel-slide.is-prev,\n.travel-slide.is-next {\n  pointer-events: auto;\n  cursor: pointer;\n}\n\n/* Short intro line under a bento card title */\n.bento-lead {\n  margin: -8px 0 18px;\n  max-width: 62ch;\n  color: var(--muted);\n  font-size: 0.92rem;\n  line-height: 1.65;\n}\n\n/* --- Home page bento --- */\n.home-page-main {\n  gap: 20px;\n}\n\n/* The hero card lets its cover photo bleed to the card edges */\n.home-hero {\n  padding: 0;\n  overflow: hidden;\n  border-radius: 18px;\n}\n\n.home-hero .profile-body {\n  padding: 0 30px 30px;\n}\n\n.bento-work .bento-link {\n  color: var(--spark);\n}\n\n.home-based .based-place {\n  margin: 0 0 4px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1rem;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.home-based .based-meta {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.86rem;\n}\n\n.tools-panel .tools-panel-title {\n  margin-bottom: 18px;\n}\n\n.tools-panel {\n  border-radius: 18px;\n}\n\n.page-summaries {\n  padding: 0;\n}\n\n@media (max-width: 600px) {\n  .home-hero .profile-body {\n    padding: 0 18px 22px;\n  }\n}\n\n/* --- Recent Work on the home page ---\n   No panel: the section is transparent and each project is its own card,\n   with the site walkthrough playing quietly in place of a still. */\n.bento-work-plain {\n  padding: 0;\n  background: transparent;\n  box-shadow: none;\n  color: var(--text);\n}\n\n.bento-work-plain .bento-work-head {\n  padding: 0 4px;\n}\n\n.bento-work-plain .bento-link {\n  color: var(--accent);\n}\n\n.bento-work-plain .bento-work-item {\n  padding: 10px;\n  border-radius: 16px;\n  background: var(--surface);\n  box-shadow: var(--shadow-sm);\n}\n\n.bento-work-plain .bento-work-item:hover {\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-4px);\n}\n\n.bento-work-plain .bento-work-label small {\n  color: var(--muted);\n}\n\n.bento-work-media {\n  width: 100%;\n  aspect-ratio: 16 / 11;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 10px;\n  background: var(--surface-2);\n  display: block;\n}\n\n/* ===========================================================\n   PORTFOLIO — CATEGORISED\n   One card per category, a filter bar above them, and every design\n   shown whole (never cropped) with the lightbox for a closer look.\n   =========================================================== */\n.pf-main {\n  gap: 20px;\n}\n\n/* Hero */\n.pf-hero {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 24px;\n  padding: 30px 32px;\n}\n\n.pf-hero-copy {\n  max-width: 560px;\n}\n\n.pf-eyebrow {\n  margin: 0 0 8px;\n  color: var(--accent);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.78rem;\n  font-weight: 700;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n}\n\n.pf-hero h1 {\n  margin: 0 0 10px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: clamp(2rem, 4vw, 3rem);\n  font-weight: 700;\n  line-height: 1.1;\n  color: var(--text);\n}\n\n.pf-hero h1 span {\n  color: var(--highlight);\n  font-weight: 800;\n}\n\n.pf-hero-copy p:last-child {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.96rem;\n  line-height: 1.65;\n}\n\n.pf-counts {\n  display: flex;\n  gap: 28px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.pf-counts li {\n  display: grid;\n  gap: 2px;\n}\n\n.pf-counts strong {\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.9rem;\n  font-weight: 700;\n  line-height: 1;\n  color: var(--accent);\n}\n\n.pf-counts span {\n  color: var(--muted);\n  font-size: 0.78rem;\n}\n\n/* Filter bar */\n.pf-filters {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.pf-filter {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 9px 16px;\n  border: 0;\n  border-radius: 999px;\n  background: var(--surface);\n  box-shadow: var(--shadow-sm);\n  color: var(--text);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.84rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.2s ease, color 0.2s ease, transform 0.2s ease;\n}\n\n.pf-filter:hover {\n  transform: translateY(-2px);\n}\n\n.pf-filter span {\n  min-width: 22px;\n  padding: 2px 7px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 700;\n  text-align: center;\n}\n\n.pf-filter.is-active {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.pf-filter.is-active span {\n  background: rgba(255, 255, 255, 0.18);\n  color: var(--paper);\n}\n\n.pf-filter:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\n/* Category cards */\n.pf-group {\n  padding: 26px 28px 28px;\n}\n\n.pf-group[hidden] {\n  display: none;\n}\n\n.pf-group-head {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n  margin-bottom: 20px;\n}\n\n.pf-group-kicker {\n  margin: 0 0 4px;\n  color: var(--accent);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.pf-group-head h2 {\n  margin: 0;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.3rem;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.pf-group-count {\n  padding: 5px 12px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--muted);\n  font-size: 0.78rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n/* Websites */\n/* Websites and designs share one grid, so every tile on the page is the same\n   size. auto-fill (not auto-fit) keeps a lone tile at tile size instead of\n   stretching it across the whole card. */\n.pf-site-grid,\n.pf-art-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(min(300px, 100%), 1fr));\n  gap: 16px;\n  align-items: stretch;\n}\n\n.pf-site {\n  display: grid;\n  grid-template-rows: auto 1fr auto;\n  gap: 12px;\n  min-width: 0;\n  padding: 10px 10px 14px;\n  border-radius: 16px;\n  background: var(--surface-2);\n  transition: transform 0.22s ease, box-shadow 0.22s ease;\n}\n\n.pf-site:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-md);\n}\n\n.pf-site-shot {\n  display: block;\n  overflow: hidden;\n  border-radius: 11px;\n  line-height: 0;\n}\n\n.pf-site-shot img {\n  width: 100%;\n  aspect-ratio: 16 / 11;\n  object-fit: cover;\n  object-position: center top;\n  transition: transform 0.4s ease;\n}\n\n.pf-site:hover .pf-site-shot img {\n  transform: scale(1.03);\n}\n\n.pf-site-info {\n  padding: 0 4px;\n}\n\n.pf-site-info h3 {\n  margin: 0 0 3px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.98rem;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.pf-site-info p {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.8rem;\n}\n\n.pf-visit {\n  justify-self: start;\n  margin-left: 4px;\n  padding: 7px 14px;\n  border-radius: 999px;\n  background: var(--brand);\n  color: var(--paper);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.78rem;\n  font-weight: 600;\n  transition: background 0.2s ease;\n}\n\n.pf-visit:hover {\n  background: var(--brand-strong);\n}\n\n.pf-empty {\n  margin: 0;\n  padding: 30px;\n  border-radius: 18px;\n  background: var(--surface);\n  color: var(--muted);\n  text-align: center;\n}\n\n@media (max-width: 600px) {\n  .pf-hero,\n  .pf-group {\n    padding: 22px 18px;\n  }\n\n  .pf-counts {\n    gap: 20px;\n  }\n\n  .pf-counts strong {\n    font-size: 1.5rem;\n  }\n}\n\n/* ===========================================================\n   DESKTOP SIDEBAR\n   Phones and tablets keep the top bar and the curved dock. From 1025px\n   up, both are swapped for a fixed dark sidebar on the left, in the\n   style of a dashboard menu.\n   =========================================================== */\n.side-nav {\n  display: none;\n}\n\n@media (min-width: 1025px) {\n  .dashboard-layout {\n    grid-template-columns: 264px minmax(0, 1fr);\n    grid-template-rows: minmax(0, 1fr);\n    align-items: start;\n  }\n\n  .topbar,\n  .dock {\n    display: none;\n  }\n\n  /* No dock to clear at the bottom any more */\n  .dashboard-main {\n    padding-bottom: 28px;\n  }\n\n  .side-nav {\n    position: sticky;\n    top: 0;\n    height: 100vh;\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    padding: 24px 18px 22px;\n    overflow-y: auto;\n    /* A soft sheen over brown-gray glass so it reads as frosted, not flat */\n    background:\n      linear-gradient(180deg, rgba(255, 255, 255, 0.07) 0%, rgba(255, 255, 255, 0) 45%),\n      var(--nav-glass);\n    backdrop-filter: blur(20px) saturate(140%);\n    -webkit-backdrop-filter: blur(20px) saturate(140%);\n    color: var(--nav-ink);\n    font-family: \"Inter\", Arial, sans-serif;\n  }\n}\n\n/* Profile block at the top */\n.side-me {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-bottom: 22px;\n  padding: 2px;\n  border-radius: 14px;\n  transition: background 0.2s ease;\n}\n\n.side-me:hover {\n  background: rgba(255, 255, 255, 0.08);\n}\n\n.side-avatar {\n  width: 46px;\n  height: 46px;\n  flex: none;\n  padding-top: 4px;\n  border: 2px solid rgba(201, 162, 74, 0.55);\n  border-radius: 999px;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n.side-me-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: 1.3;\n}\n\n.side-me-text strong {\n  color: var(--paper);\n  font-size: 0.95rem;\n  font-weight: 600;\n}\n\n.side-me-text small {\n  color: rgba(255, 255, 255, 0.66);\n  font-size: 0.76rem;\n}\n\n/* Menu */\n.side-label {\n  margin: 0 0 8px 12px;\n  color: rgba(255, 255, 255, 0.5);\n  font-size: 0.7rem;\n  font-weight: 600;\n  letter-spacing: 0.16em;\n  text-transform: uppercase;\n}\n\n.side-links {\n  display: grid;\n  gap: 4px;\n}\n\n.side-link {\n  display: flex;\n  align-items: center;\n  gap: 13px;\n  padding: 11px 14px;\n  border-radius: 12px;\n  color: rgba(255, 255, 255, 0.8);\n  font-size: 0.93rem;\n  font-weight: 500;\n  transition: background 0.2s ease, color 0.2s ease;\n}\n\n.side-link img {\n  width: 22px;\n  height: 22px;\n  flex: none;\n  object-fit: contain;\n}\n\n.side-link:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--paper);\n}\n\n.side-link.is-active {\n  background: rgba(201, 162, 74, 0.18);\n  color: var(--paper);\n  font-weight: 600;\n}\n\n.side-link.is-active span {\n  color: var(--spark);\n}\n\n.side-link:focus-visible,\n.side-me:focus-visible,\n.side-cta:focus-visible {\n  outline: 2px solid var(--spark);\n  outline-offset: 2px;\n}\n\n/* Footer: call to action, socials, theme switch */\n.side-foot {\n  display: grid;\n  gap: 14px;\n  margin-top: auto;\n  padding-top: 20px;\n}\n\n.side-cta {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 12px 16px;\n  border-radius: 12px;\n  background: var(--spark);\n  color: var(--brand-strong);\n  font-size: 0.9rem;\n  font-weight: 700;\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.side-cta:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 10px 22px -10px rgba(201, 162, 74, 0.8);\n}\n\n.side-foot-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.side-socials {\n  display: flex;\n  gap: 6px;\n}\n\n/* Only the disc behind each logo changes on hover */\n.side-socials a {\n  width: 36px;\n  height: 36px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.1);\n  transition: background 0.2s ease;\n}\n\n.side-socials a:hover {\n  background: rgba(201, 162, 74, 0.3);\n}\n\n.side-socials img {\n  width: 19px;\n  height: 19px;\n  object-fit: contain;\n}\n\n/* Small laptops: with the sidebar taking 264px, the two-column bento would\n   squeeze its right column, so stack it until there is room again */\n@media (min-width: 1025px) and (max-width: 1180px) {\n  .bento {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n/* Design tiles mirror the website tiles: tinted card, fixed 16:11 frame,\n   title and caption underneath. Inside the frame the design is contained,\n   not cropped, so the whole piece stays visible; the lightbox shows it big. */\n.pf-art {\n  display: grid;\n  grid-template-rows: auto 1fr;\n  gap: 12px;\n  min-width: 0;\n  margin: 0;\n  padding: 10px 10px 14px;\n  border-radius: 16px;\n  background: var(--surface-2);\n  transition: transform 0.22s ease, box-shadow 0.22s ease;\n}\n\n.pf-art:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-md);\n}\n\n.pf-art .graphic-preview {\n  aspect-ratio: 16 / 11;\n  padding: 2px;\n  border-radius: 11px;\n  background: var(--surface);\n  line-height: 0;\n}\n\n.pf-art .graphic-preview img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  transition: transform 0.4s ease;\n}\n\n.pf-art:hover .graphic-preview img {\n  transform: scale(1.03);\n}\n\n.pf-art figcaption {\n  display: grid;\n  align-content: start;\n  gap: 3px;\n  padding: 0 4px;\n}\n\n.pf-art figcaption strong {\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.98rem;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.pf-art figcaption span {\n  color: var(--muted);\n  font-size: 0.8rem;\n}\n\n.cd-copy svg{\n  width: 20px;\n  height: 20px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.9;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.cd-copy {\n  width: 36px;\n  height: 36px;\n  flex: none;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 10px;\n  background: var(--surface);\n  color: var(--muted);\n  cursor: pointer;\n  transition: background 0.2s ease, color 0.2s ease;\n}\n\n.cd-copy:hover {\n  color: var(--accent);\n}\n\n.cd-copy.is-copied {\n  background: var(--spark);\n  color: var(--brand-strong);\n}\n\n/* Live clocks */\n.cd-time-label {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 10px;\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n.cd-live {\n  width: 8px;\n  height: 8px;\n  flex: none;\n  border-radius: 999px;\n  background: var(--spark);\n  box-shadow: 0 0 0 3px rgba(201, 162, 74, 0.22);\n}\n\n.cd-zones {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(min(128px, 100%), 1fr));\n  gap: 8px;\n  margin-bottom: 22px;\n}\n\n.cd-zone {\n  display: grid;\n  gap: 2px;\n  padding: 12px 14px;\n  border-radius: 14px;\n  background: var(--surface-2);\n}\n\n.cd-zone.is-home {\n  background: rgba(201, 162, 74, 0.18);\n}\n\n.cd-zone-abbr {\n  color: var(--accent);\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n}\n\n.cd-zone-time {\n  color: var(--text);\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1.2rem;\n  font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  line-height: 1.2;\n}\n\n.cd-zone-meta {\n  color: var(--muted);\n  font-size: 0.74rem;\n}\n\n.cd-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 12px 18px;\n  border-radius: 12px;\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 0.9rem;\n  font-weight: 600;\n  text-align: center;\n  transition: background 0.2s ease, transform 0.2s ease;\n}\n\n.cd-btn:hover {\n  transform: translateY(-2px);\n}\n\n.cd-btn-main {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.cd-btn-main:hover {\n  background: var(--brand-strong);\n}\n\n.cd-btn-alt {\n  background: rgba(201, 162, 74, 0.16);\n  color: var(--accent);\n}\n\n.cd-btn-alt:hover {\n  background: rgba(201, 162, 74, 0.28);\n}\n\n/* ===========================================================\n   TYPE: Inter throughout, with bold, tight, uppercase headlines and small\n   letter-spaced labels led by a gold dot.\n   =========================================================== */\nh1,\nh2,\nh3 {\n  letter-spacing: -0.02em;\n}\n\n.home-hero h1,\n.pf-hero h1,\n.bento-title h1 {\n  font-size: clamp(2.1rem, 3.6vw, 3.4rem);\n  font-weight: 800;\n  line-height: 1.04;\n  letter-spacing: -0.03em;\n  text-transform: uppercase;\n}\n\n.home-hero h1 span,\n.pf-hero h1 span {\n  color: var(--highlight);\n  font-weight: 800;\n}\n\n.pf-eyebrow,\n.pf-group-kicker,\n.section-label,\n.vision-eyebrow{\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.pf-eyebrow,\n.pf-group-kicker,\n.section-label {\n  color: var(--text);\n}\n\n.pf-eyebrow::before,\n.pf-group-kicker::before,\n.section-label::before,\n.vision-eyebrow::before{\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  flex: none;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n/* ===========================================================\n   NAV: brown-gray glass with simple line icons\n   =========================================================== */\n.nav-ic {\n  width: 22px;\n  height: 22px;\n  flex: none;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n/* Sidebar: profile, menu and footer stack together at the top, no big gaps */\n.side-label {\n  margin-top: 26px;\n}\n\n.side-foot {\n  margin-top: 26px;\n  padding-top: 0;\n}\n\n.side-links {\n  gap: 4px;\n}\n\n.side-link {\n  padding: 11px 14px;\n  color: rgba(247, 245, 239, 0.78);\n  font-size: 0.96rem;\n}\n\n.side-link:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--nav-ink);\n}\n\n.side-link.is-active {\n  background: rgba(201, 162, 74, 0.16);\n  color: var(--spark);\n}\n\n.side-link.is-active span {\n  color: var(--spark);\n}\n\n.side-me-text strong {\n  color: var(--nav-ink);\n}\n\n.side-me-text small,\n.side-label {\n  color: rgba(247, 245, 239, 0.6);\n}\n\n/* Dock: light icons on the glass; the lifted icon turns forest green on the gold bubble */\n.dock-icon {\n  color: inherit;\n}\n\n.dock-item {\n  color: rgba(247, 245, 239, 0.75);\n}\n\n.dock-item.dipped .dock-icon {\n  color: #1d3a2e;\n}\n\n.dock-item:hover .dock-label {\n  color: var(--nav-ink);\n}\n\n/* ===========================================================\n   HOME HERO (UI pass)\n   Cover spans the full card, compact side-by-side buttons, and the stats\n   sit in the text column as a quiet row that supports the headline.\n   =========================================================== */\n.home-hero .profile-banner {\n  width: 100%;\n  aspect-ratio: auto;\n  height: clamp(200px, 24vw, 400px);\n  max-height: none;\n}\n\n.home-hero .profile-body {\n  grid-template-columns: 184px minmax(0, 1fr);\n  gap: 40px;\n  padding: 0 44px 44px;\n}\n\n.home-hero .profile-main {\n  padding-top: 30px;\n}\n\n.hero-eyebrow {\n  margin: 0 0 14px;\n  font-size: 0.8rem;\n  font-weight: 700;\n}\n\n.home-hero .profile-main .description {\n  max-width: 58ch;\n  margin: 0 0 28px;\n  font-size: 1.02rem;\n  line-height: 1.7;\n}\n\n.home-hero .profile-actions {\n  width: auto;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n}\n\n.home-hero .profile-actions .button {\n  width: auto;\n  min-height: 48px;\n  gap: 10px;\n  padding: 0 26px;\n  border-radius: 12px;\n  font-size: 0.95rem;\n  font-weight: 600;\n  transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.home-hero .profile-actions .button:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n}\n\n/* Stats: a plain row, no card, numbers do the talking */\n.home-hero .hero-stats {\n  width: auto;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 18px 44px;\n  margin: 34px 0 0;\n  padding: 0;\n  background: none;\n  box-shadow: none;\n  text-align: left;\n}\n\n.home-hero .hero-stats li {\n  display: grid;\n  gap: 4px;\n}\n\n.home-hero .hero-stats strong {\n  color: var(--text);\n  font-size: 1.9rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1;\n}\n\n.home-hero .hero-stats span {\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 600;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n@media (max-width: 800px) {\n  .home-hero .profile-body {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 0;\n    padding: 0 22px 30px;\n  }\n\n  .home-hero .profile-main {\n    padding-top: 18px;\n  }\n\n  .home-hero .hero-stats {\n    gap: 16px 30px;\n  }\n\n  .home-hero .hero-stats strong {\n    font-size: 1.5rem;\n  }\n}\n\n@media (max-width: 480px) {\n  .home-hero .profile-actions .button {\n    flex: 1 1 100%;\n  }\n}\n\n/* ===========================================================\n   CONTACT PAGE\n   =========================================================== */\n.ct-hero {\n  align-items: center;\n}\n\n.ct-hero .contact-avatar-ring {\n  margin: 0;\n  flex: none;\n}\n\n.ct-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(360px, 100%), 1fr));\n  gap: 16px;\n  align-items: start;\n}\n\n.cf-error {\n  margin: 0;\n  color: #b3261e;\n  font-size: 0.85rem;\n  font-weight: 600;\n}\n\n/* ===========================================================\n   RESUME PAGE\n   =========================================================== */\n.rs-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.rs-facts {\n  display: grid;\n  gap: 12px;\n  margin: 0;\n}\n\n.rs-facts div {\n  display: grid;\n  gap: 2px;\n}\n\n.rs-facts dt {\n  color: var(--muted);\n  font-size: 0.7rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.rs-facts dd {\n  margin: 0;\n  color: var(--text);\n  font-size: 0.92rem;\n  font-weight: 600;\n}\n\n/* Experience: a dot per role, no connecting lines */\n.rs-timeline {\n  display: grid;\n  gap: 14px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.rs-timeline li {\n  position: relative;\n  display: grid;\n  gap: 2px;\n  padding-left: 20px;\n}\n\n.rs-timeline li::before {\n  content: \"\";\n  position: absolute;\n  top: 7px;\n  left: 0;\n  width: 8px;\n  height: 8px;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n.rs-timeline strong {\n  color: var(--text);\n  font-size: 0.95rem;\n  font-weight: 700;\n}\n\n.rs-timeline span {\n  color: var(--muted);\n  font-size: 0.85rem;\n}\n\n/* The resume itself, shown whole on a soft backdrop like a sheet on a desk */\n.rs-preview {\n  padding: 22px;\n  background: var(--surface-2);\n}\n\n.rs-sheet {\n  display: block;\n  max-width: 720px;\n  margin: 0 auto;\n  border-radius: 6px;\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n  overflow: hidden;\n  line-height: 0;\n  transition: transform 0.25s ease;\n}\n\n.rs-sheet:hover {\n  transform: translateY(-3px);\n}\n\n.rs-sheet img {\n  width: 100%;\n  height: auto;\n}\n\n@media (max-width: 600px) {\n  .rs-preview {\n    padding: 12px;\n  }\n\n  .ct-hero .contact-avatar-ring {\n    display: none;\n  }\n}\n\n/* Agency block on the Resume page and the client note on Home */\n.rs-agency {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-bottom: 18px;\n  padding: 12px;\n  border-radius: 14px;\n  background: var(--surface-2);\n}\n\n.rs-agency img {\n  width: 44px;\n  height: 44px;\n  flex: none;\n  object-fit: contain;\n}\n\n.rs-agency div {\n  display: grid;\n  gap: 1px;\n}\n\n.rs-agency strong {\n  color: var(--text);\n  font-size: 0.95rem;\n  font-weight: 700;\n}\n\n.rs-agency span {\n  color: var(--muted);\n  font-size: 0.8rem;\n}\n\n.rs-clients-label {\n  margin: 0 0 12px;\n  color: var(--muted);\n  font-size: 0.7rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.rs-timeline + .rs-clients-label {\n  margin-top: 22px;\n}\n\n/* ===========================================================\n   HOME: closing summary cards\n   Each card is one link. The last one is the call to action, so it\n   carries the forest gradient and a gold button.\n   =========================================================== */\n.sum-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(270px, 100%), 1fr));\n  gap: 16px;\n}\n\n.sum-card {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  min-height: 250px;\n  padding: 24px 24px 22px;\n  border-radius: 18px;\n  background: var(--surface);\n  box-shadow: var(--shadow-sm);\n  color: var(--text);\n  transition: transform 0.22s ease, box-shadow 0.22s ease;\n}\n\n.sum-card:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-md);\n}\n\n.sum-top {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.sum-avatar,\n.sum-logo,\n.sum-icon {\n  width: 46px;\n  height: 46px;\n  flex: none;\n  border-radius: 14px;\n}\n\n.sum-avatar {\n  padding-top: 4px;\n  border-radius: 999px;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n.sum-logo {\n  padding: 2px;\n  background: var(--surface-2);\n  object-fit: contain;\n}\n\n.sum-icon {\n  display: grid;\n  place-items: center;\n  background: rgba(201, 162, 74, 0.22);\n  color: var(--spark);\n}\n\n.sum-icon svg {\n  width: 22px;\n  height: 22px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.9;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.sum-kicker {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.sum-kicker::before {\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n.sum-card h3 {\n  margin: 4px 0 0;\n  font-size: 1.18rem;\n  font-weight: 700;\n  line-height: 1.3;\n  color: inherit;\n}\n\n.sum-card p {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.9rem;\n  line-height: 1.6;\n}\n\n.sum-clients {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.sum-clients li {\n  padding: 5px 11px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 0.78rem;\n  font-weight: 500;\n}\n\n.sum-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  margin-top: auto;\n  padding-top: 8px;\n  color: var(--text);\n  font-size: 0.9rem;\n  font-weight: 700;\n}\n\n.sum-link span {\n  color: var(--spark-ink);\n  transition: transform 0.2s ease;\n}\n\n.sum-card:hover .sum-link span {\n  transform: translateX(4px);\n}\n\n/* The call-to-action card */\n.sum-card-cta {\n  background:\n    radial-gradient(120% 90% at 100% 0%, rgba(201, 162, 74, 0.22), transparent 55%),\n    var(--gradient);\n  color: var(--paper);\n}\n\n.sum-card-cta .sum-kicker {\n  color: rgba(247, 245, 239, 0.7);\n}\n\n.sum-card-cta .hours-status {\n  color: rgba(247, 245, 239, 0.85);\n  font-size: 0.9rem;\n}\n\n.sum-card-cta .hours-status.is-online {\n  color: var(--paper);\n}\n\n.sum-card-cta .status-dot {\n  background: rgba(247, 245, 239, 0.55);\n}\n\n.sum-card-cta .sum-hours {\n  color: rgba(247, 245, 239, 0.65);\n  font-size: 0.84rem;\n}\n\n.sum-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  margin-top: auto;\n  padding: 12px 18px;\n  border-radius: 12px;\n  background: var(--spark);\n  color: var(--brand-strong);\n  font-size: 0.92rem;\n  font-weight: 700;\n  transition: background 0.2s ease;\n}\n\n.sum-card-cta:hover .sum-btn {\n  background: #d8b35e;\n}\n\n/* ===========================================================\n   ABOUT: closing call-to-action band\n   =========================================================== */\n.cta-band {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 22px;\n  padding: 30px 32px;\n  background:\n    radial-gradient(90% 120% at 100% 0%, rgba(201, 162, 74, 0.24), transparent 55%),\n    var(--gradient);\n  color: var(--paper);\n}\n\n.cta-band-copy {\n  max-width: 520px;\n}\n\n.cta-band-kicker {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 8px;\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.cta-band-kicker::before {\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n.cta-band h2 {\n  margin: 0 0 8px;\n  color: var(--paper);\n  font-size: clamp(1.35rem, 2.4vw, 1.8rem);\n  font-weight: 800;\n  line-height: 1.15;\n}\n\n.cta-band-copy p:last-child {\n  margin: 0;\n  color: rgba(247, 245, 239, 0.75);\n  font-size: 0.95rem;\n}\n\n.cta-band-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.cta-band-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 13px 22px;\n  border-radius: 12px;\n  font-size: 0.92rem;\n  font-weight: 700;\n  transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.cta-band-btn:hover {\n  transform: translateY(-2px);\n}\n\n.cta-band-btn-main {\n  background: var(--spark);\n  color: var(--brand-strong);\n}\n\n.cta-band-btn-alt {\n  background: rgba(255, 255, 255, 0.12);\n  color: var(--paper);\n}\n\n.cta-band-btn-alt:hover {\n  background: rgba(255, 255, 255, 0.2);\n}\n\n/* ===========================================================\n   HOME: agency and clients, drawn as a small org chart\n   The agency sits on top; a gold trunk splits into one branch per client,\n   so it reads at a glance that the clients sit under the agency.\n   =========================================================== */\n.cl-card {\n  padding: 28px 30px 32px;\n}\n\n.cl-head {\n  margin-bottom: 26px;\n  text-align: center;\n}\n\n.cl-head .section-label {\n  margin: 0 0 6px;\n}\n\n.cl-head .bento-card-title {\n  margin: 0;\n  font-size: 1.35rem;\n  font-weight: 800;\n}\n\n.cl-tree {\n  --branch: rgba(201, 162, 74, 0.6);\n  --drop: 28px;\n  display: grid;\n  justify-items: center;\n}\n\n.cl-root {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 14px 24px 14px 14px;\n  border-radius: 16px;\n  background:\n    radial-gradient(120% 140% at 100% 0%, rgba(201, 162, 74, 0.22), transparent 60%),\n    var(--gradient);\n  color: var(--paper);\n  box-shadow: var(--shadow-md);\n}\n\n.cl-root img {\n  width: 54px;\n  height: 54px;\n  flex: none;\n  padding: 5px;\n  border-radius: 12px;\n  background: #ffffff;\n  object-fit: contain;\n}\n\n.cl-root div {\n  display: grid;\n  gap: 2px;\n}\n\n.cl-root strong {\n  font-size: 1.02rem;\n  font-weight: 700;\n}\n\n.cl-root span {\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.8rem;\n}\n\n/* Trunk down from the agency */\n.cl-root::after {\n  content: \"\";\n  position: absolute;\n  top: 100%;\n  left: 50%;\n  width: 2px;\n  height: var(--drop);\n  background: var(--branch);\n  transform: translateX(-50%);\n}\n\n.cl-leaves {\n  position: relative;\n  width: 100%;\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 16px;\n  margin: var(--drop) 0 0;\n  padding: var(--drop) 0 0;\n  list-style: none;\n}\n\n/* Crossbar from the first client's centre to the last one's */\n.cl-leaves::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: calc(12.5% - 6px);\n  right: calc(12.5% - 6px);\n  height: 2px;\n  background: var(--branch);\n}\n\n.cl-leaves li {\n  position: relative;\n}\n\n/* One branch down to each client */\n.cl-leaves li::before {\n  content: \"\";\n  position: absolute;\n  top: calc(var(--drop) * -1);\n  left: 50%;\n  width: 2px;\n  height: var(--drop);\n  background: var(--branch);\n  transform: translateX(-50%);\n}\n\n.cl-leaves a {\n  display: grid;\n  place-items: center;\n  height: 112px;\n  padding: 14px;\n  border-radius: 16px;\n  background: var(--surface-2);\n  transition: transform 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;\n}\n\n.cl-leaves a:hover {\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-4px);\n}\n\n.cl-leaves img {\n  max-width: 82%;\n  max-height: 74px;\n  width: auto;\n  height: auto;\n  object-fit: contain;\n}\n\n/* Two per row on small screens: the branches would not line up, so drop them */\n@media (max-width: 700px) {\n  .cl-card {\n    padding: 24px 18px;\n  }\n\n  .cl-leaves {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 12px;\n    margin-top: 18px;\n    padding-top: 0;\n  }\n\n  .cl-root::after,\n  .cl-leaves::before,\n  .cl-leaves li::before {\n    display: none;\n  }\n\n  .cl-leaves a {\n    height: 96px;\n  }\n}\n\n/* ===========================================================\n   HOME HERO: compact arrangement\n   Photo | text | stats panel side by side, a shorter cover, and a\n   slightly smaller headline, so the hero is much less tall.\n   =========================================================== */\n.home-hero .profile-banner {\n  height: clamp(150px, 16vw, 250px);\n}\n\n.home-hero .profile-body {\n  grid-template-columns: 184px minmax(0, 1fr) minmax(190px, 230px);\n  gap: 36px;\n  align-items: start;\n  padding: 0 40px 34px;\n}\n\n.home-hero .profile-main {\n  padding-top: 22px;\n}\n\n.home-hero h1 {\n  font-size: clamp(1.9rem, 2.7vw, 2.75rem);\n  margin-bottom: 14px;\n}\n\n.hero-eyebrow {\n  margin-bottom: 10px;\n}\n\n.home-hero .profile-main .description {\n  max-width: 60ch;\n  margin-bottom: 22px;\n  font-size: 0.98rem;\n  line-height: 1.65;\n}\n\n/* Stats become a soft panel in the right column */\n.home-hero .hero-stats {\n  align-self: center;\n  display: grid;\n  gap: 18px;\n  margin: 22px 0 0;\n  padding: 22px 24px;\n  border-radius: 18px;\n  background: var(--surface-2);\n}\n\n.home-hero .hero-stats li {\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n}\n\n.home-hero .hero-stats strong {\n  min-width: 2.2ch;\n  color: var(--spark-ink);\n  font-size: 2rem;\n}\n\n/* Narrower screens: stats fold back under the text as a row */\n@media (max-width: 1280px) {\n  .home-hero .profile-body {\n    grid-template-columns: 184px minmax(0, 1fr);\n  }\n\n  .home-hero .hero-stats {\n    grid-column: 2;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 14px 36px;\n    margin-top: 0;\n    padding: 16px 22px;\n  }\n\n  .home-hero .hero-stats li {\n    display: grid;\n    gap: 2px;\n  }\n}\n\n@media (max-width: 800px) {\n  .home-hero .profile-body {\n    grid-template-columns: minmax(0, 1fr);\n    padding: 0 22px 26px;\n  }\n\n  .home-hero .hero-stats {\n    grid-column: auto;\n    margin-top: 20px;\n  }\n}\n\n/* ===========================================================\n   ABOUT: How I Work as numbered step tiles\n   =========================================================== */\n.bento-how .section-label {\n  margin: 0 0 6px;\n}\n\n.bento-how .how-title {\n  margin-bottom: 20px;\n}\n\n.how-grid {\n  grid-template-columns: repeat(auto-fit, minmax(min(240px, 100%), 1fr));\n  gap: 14px;\n}\n\n.how-item {\n  gap: 10px;\n  padding: 20px 20px 22px;\n  border-radius: 16px;\n  background: var(--surface-2);\n  transition: transform 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;\n}\n\n.how-item:hover {\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-4px);\n}\n\n.how-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 6px;\n}\n\n.how-num {\n  color: var(--spark-ink);\n  font-size: 2.2rem;\n  font-weight: 800;\n  letter-spacing: -0.04em;\n  line-height: 1;\n}\n\n.how-icon {\n  width: 46px;\n  height: 46px;\n  border-radius: 999px;\n  background: rgba(201, 162, 74, 0.22);\n  color: var(--brand);\n}\n\n.how-item h3 {\n  margin: 0;\n  font-size: 1.08rem;\n  font-weight: 700;\n}\n\n.how-item p {\n  font-size: 0.88rem;\n  line-height: 1.6;\n}\n\n.how-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin: 4px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.how-tags li {\n  padding: 4px 10px;\n  border-radius: 999px;\n  background: var(--surface);\n  color: var(--text);\n  font-size: 0.74rem;\n  font-weight: 500;\n}\n\n.how-item:hover .how-tags li {\n  background: var(--surface-2);\n}\n\n/* Hero stats panel fix: an older rule set three columns on .hero-stats, which\n   squeezed the panel's items into each other. One stat per row, number above\n   its label. */\n.home-hero .hero-stats {\n  grid-template-columns: minmax(0, 1fr);\n  min-width: 0;\n}\n\n.home-hero .hero-stats li {\n  display: grid;\n  gap: 2px;\n}\n\n@media (max-width: 1280px) {\n  .home-hero .hero-stats li {\n    display: grid;\n  }\n}\n\n/* ===========================================================\n   PORTFOLIO (UI pass)\n   =========================================================== */\n\n/* Dark hero so the page opens with some weight */\n.pf-hero-dark {\n  background:\n    radial-gradient(90% 140% at 100% 0%, rgba(201, 162, 74, 0.24), transparent 55%),\n    var(--gradient);\n  color: var(--paper);\n}\n\n.pf-hero-dark .pf-eyebrow,\n.pf-hero-dark h1 {\n  color: var(--paper);\n}\n\n.pf-hero-dark h1 span {\n  color: var(--spark);\n}\n\n.pf-hero-dark .pf-hero-copy p:last-child {\n  color: rgba(247, 245, 239, 0.75);\n}\n\n.pf-hero-dark .pf-counts li {\n  padding: 14px 18px;\n  border-radius: 14px;\n  background: rgba(255, 255, 255, 0.08);\n}\n\n.pf-hero-dark .pf-counts strong {\n  color: var(--spark);\n}\n\n.pf-hero-dark .pf-counts span {\n  color: rgba(247, 245, 239, 0.7);\n}\n\n/* Filter bar stays in reach while scrolling */\n.pf-filters {\n  position: sticky;\n  top: 72px;\n  z-index: 30;\n  width: fit-content;\n  max-width: 100%;\n  padding: 2px;\n  border-radius: 999px;\n  background: rgba(247, 245, 239, 0.86);\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  box-shadow: var(--shadow-sm);\n}\n\n.pf-filter {\n  box-shadow: none;\n  background: transparent;\n}\n\n.pf-filter:hover {\n  background: rgba(19, 42, 33, 0.06);\n  transform: none;\n}\n\n@media (min-width: 1025px) {\n  .pf-filters {\n    top: 14px;\n  }\n}\n\n/* Category headers get an icon badge */\n.pf-group-head {\n  justify-content: flex-start;\n  align-items: center;\n  gap: 14px;\n}\n\n.pf-group-head > div {\n  flex: 1;\n  min-width: 0;\n}\n\n.pf-group-icon {\n  width: 48px;\n  height: 48px;\n  flex: none;\n  display: grid;\n  place-items: center;\n  border-radius: 14px;\n  background: rgba(201, 162, 74, 0.2);\n  color: var(--brand);\n}\n\n.pf-group-icon svg {\n  width: 24px;\n  height: 24px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n/* Websites: bigger, two per row, framed like a browser window */\n.pf-group[data-category=\"websites\"] .pf-site-grid {\n  grid-template-columns: repeat(auto-fill, minmax(min(460px, 100%), 1fr));\n  gap: 20px;\n}\n\n.pf-site {\n  grid-template-columns: minmax(0, 1fr) auto;\n  grid-template-rows: auto auto;\n  align-items: center;\n  gap: 14px 12px;\n  padding: 12px 12px 14px;\n}\n\n.pf-site-shot {\n  grid-column: 1 / -1;\n  border-radius: 12px;\n  background: var(--surface);\n  box-shadow: 0 1px 2px rgba(19, 42, 33, 0.08);\n}\n\n.pf-browser-bar {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 10px 12px;\n  line-height: 1;\n  background: var(--surface);\n}\n\n.pf-browser-bar i {\n  width: 9px;\n  height: 9px;\n  border-radius: 999px;\n  background: #e5e0d2;\n}\n\n.pf-browser-bar i:first-child {\n  background: #e8a598;\n}\n\n.pf-browser-bar i:nth-child(2) {\n  background: #e8cf8f;\n}\n\n.pf-browser-bar i:nth-child(3) {\n  background: #b5d3b0;\n}\n\n.pf-browser-bar span {\n  flex: 1;\n  margin-left: 8px;\n  padding: 5px 10px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--muted);\n  font-size: 0.72rem;\n  line-height: 1.2;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.pf-site-shot img {\n  aspect-ratio: 16 / 10;\n  border-radius: 0 0 12px 12px;\n}\n\n.pf-site-info {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 0 4px;\n  min-width: 0;\n}\n\n.pf-site-logo {\n  width: 40px;\n  height: 40px;\n  flex: none;\n  padding: 4px;\n  border-radius: 10px;\n  background: var(--surface);\n  object-fit: contain;\n}\n\n.pf-site-info h3 {\n  margin: 0;\n}\n\n.pf-visit {\n  justify-self: end;\n  margin: 0 4px 0 0;\n}\n\n/* The page ends on a clear next step */\n.pf-main .cta-band {\n  margin-top: 4px;\n}\n\n@media (max-width: 600px) {\n  .pf-filters {\n    width: 100%;\n    border-radius: 18px;\n    overflow-x: auto;\n    flex-wrap: nowrap;\n  }\n\n  .pf-filter {\n    flex: none;\n  }\n\n  .pf-hero-dark .pf-counts li {\n    padding: 10px 12px;\n  }\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* ===========================================================\n   CONTACT: Gmail-style compose window\n   =========================================================== */\n.gm-card {\n  padding: 0;\n  overflow: hidden;\n}\n\n.gm-window {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n.gm-head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 14px 20px;\n  background: var(--surface-2);\n  color: var(--text);\n  font-size: 0.92rem;\n  font-weight: 600;\n}\n\n.gm-head img {\n  width: 24px;\n  height: 24px;\n  object-fit: contain;\n}\n\n.gm-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin: 0 20px;\n  padding: 12px 0;\n  box-shadow: inset 0 -1px 0 var(--border);\n}\n\n.gm-label {\n  width: 58px;\n  flex: none;\n  color: var(--muted);\n  font-size: 0.86rem;\n}\n\n.gm-to {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 4px 12px 4px 4px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  font-size: 0.86rem;\n}\n\n.gm-to img {\n  width: 26px;\n  height: 26px;\n  flex: none;\n  padding-top: 2px;\n  border-radius: 999px;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n.gm-to span {\n  color: var(--text);\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.gm-to small {\n  overflow: hidden;\n  color: var(--muted);\n  font-size: 0.8rem;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gm-row input {\n  flex: 1;\n  min-width: 0;\n  padding: 4px 0;\n  border: 0;\n  background: transparent;\n  color: var(--text);\n  font: inherit;\n  font-size: 0.95rem;\n}\n\n.gm-row input:focus,\n.gm-body textarea:focus {\n  outline: none;\n}\n\n.gm-row:focus-within {\n  box-shadow: inset 0 -2px 0 var(--spark);\n}\n\n.gm-body {\n  flex: 1;\n  display: flex;\n  margin: 0 20px;\n  padding: 14px 0 6px;\n}\n\n.gm-body textarea {\n  flex: 1;\n  min-height: 170px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--text);\n  font: inherit;\n  font-size: 0.95rem;\n  line-height: 1.6;\n  resize: vertical;\n}\n\n.gm-body textarea::placeholder,\n.gm-row input::placeholder {\n  color: var(--muted);\n  opacity: 0.8;\n}\n\n.gm-error {\n  margin: 0 20px 6px;\n}\n\n.gm-actions {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 10px;\n  padding: 14px 20px 18px;\n}\n\n.gm-send,\n.gm-alt {\n  display: inline-flex;\n  align-items: center;\n  gap: 9px;\n  padding: 11px 20px;\n  border: 0;\n  border-radius: 999px;\n  font: inherit;\n  font-size: 0.9rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;\n}\n\n.gm-send img,\n.gm-alt img {\n  width: 20px;\n  height: 20px;\n  padding: 2px;\n  border-radius: 6px;\n  background: #ffffff;\n  object-fit: contain;\n}\n\n.gm-send {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.gm-send:hover {\n  background: var(--brand-strong);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-2px);\n}\n\n.gm-alt {\n  background: var(--surface-2);\n  color: var(--text);\n}\n\n.gm-alt:hover {\n  background: rgba(37, 211, 102, 0.16);\n  transform: translateY(-2px);\n}\n\n.gm-link {\n  margin-left: auto;\n  padding: 6px 4px;\n  border: 0;\n  background: none;\n  color: var(--muted);\n  font: inherit;\n  font-size: 0.82rem;\n  text-decoration: underline;\n  text-underline-offset: 3px;\n  cursor: pointer;\n}\n\n.gm-link:hover {\n  color: var(--text);\n}\n\n@media (max-width: 480px) {\n  .gm-to small {\n    display: none;\n  }\n\n  .gm-link {\n    margin-left: 0;\n  }\n}\n\n/* ===========================================================\n   CONTACT: Contact Details card\n   A forest banner with photo, name and live status, then tappable\n   tiles for each way to reach Venus, then world clocks.\n   =========================================================== */\n.cd-rich {\n  padding: 0;\n  overflow: hidden;\n}\n\n.cd-banner {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  align-items: center;\n  gap: 14px 16px;\n  padding: 22px 24px;\n  background:\n    radial-gradient(120% 140% at 100% 0%, rgba(201, 162, 74, 0.24), transparent 60%),\n    var(--gradient);\n  color: var(--paper);\n}\n\n.cd-banner-photo {\n  width: 64px;\n  height: 64px;\n  padding-top: 5px;\n  border: 3px solid rgba(201, 162, 74, 0.7);\n  border-radius: 999px;\n  background: #e5e0d2;\n  object-fit: cover;\n  object-position: 50% 0;\n}\n\n.cd-banner-name {\n  display: grid;\n  gap: 2px;\n}\n\n.cd-banner-name strong {\n  font-size: 1.15rem;\n  font-weight: 700;\n}\n\n.cd-banner-name span {\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.86rem;\n}\n\n.cd-status {\n  grid-column: 1 / -1;\n  width: fit-content;\n  margin: 0;\n  padding: 7px 14px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.1);\n  color: rgba(247, 245, 239, 0.88);\n  font-size: 0.84rem;\n}\n\n.cd-status.is-online {\n  color: var(--paper);\n}\n\n.cd-status .status-dot {\n  background: rgba(247, 245, 239, 0.55);\n}\n\n.cd-tiles {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(230px, 100%), 1fr));\n  gap: 10px;\n  padding: 20px 22px 4px;\n}\n\n.cd-tile {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n  padding: 14px;\n  border-radius: 14px;\n  background: var(--surface-2);\n  transition: background 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;\n}\n\n.cd-tile:hover {\n  background: var(--surface);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-2px);\n}\n\n.cd-tile-ic {\n  width: 42px;\n  height: 42px;\n  flex: none;\n  display: grid;\n  place-items: center;\n  border-radius: 12px;\n  background: var(--surface);\n  box-shadow: 0 1px 2px rgba(19, 42, 33, 0.08);\n}\n\n.cd-tile-ic img {\n  width: 22px;\n  height: 22px;\n  object-fit: contain;\n}\n\n.cd-tile-ic svg {\n  width: 21px;\n  height: 21px;\n  fill: none;\n  stroke: var(--brand);\n  stroke-width: 1.9;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.cd-tile-text {\n  display: grid;\n  flex: 1;\n  gap: 1px;\n  min-width: 0;\n}\n\n.cd-tile-text small {\n  color: var(--muted);\n  font-size: 0.68rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.cd-tile-text a,\n.cd-tile-text span {\n  color: var(--text);\n  font-size: 0.9rem;\n  font-weight: 600;\n  overflow-wrap: anywhere;\n}\n\n.cd-tile-text a:hover {\n  color: var(--highlight);\n}\n\n.cd-tile .cd-copy {\n  background: var(--surface);\n}\n\n.cd-clock {\n  padding: 16px 22px 22px;\n}\n\n.cd-clock .cd-zones {\n  margin-bottom: 0;\n}\n\n/* ===========================================================\n   MOBILE PASS (phones)\n   Shorter hero, horizontal scroll rows instead of tall stacks, and\n   compact lists, so the page stops being eleven screens long.\n   =========================================================== */\n@media (max-width: 800px) {\n  .home-hero .profile-banner {\n    height: 140px;\n  }\n\n  .home-hero .profile-body {\n    row-gap: 0;\n  }\n\n  .home-hero .profile-side {\n    justify-items: start;\n  }\n\n  .home-hero .profile-photo {\n    width: 104px;\n    height: 104px;\n    margin-top: -56px;\n    padding-top: 8px;\n    border-width: 4px;\n  }\n\n  .home-hero .profile-main {\n    padding-top: 14px;\n  }\n\n  .home-hero h1 {\n    font-size: 1.75rem;\n  }\n\n  .home-hero .profile-main .description {\n    margin-bottom: 18px;\n    font-size: 0.94rem;\n  }\n}\n\n@media (max-width: 600px) {\n  /* Top bar: logo and avatar only; the socials live in the dock pages */\n  .topbar-socials {\n    display: none;\n  }\n\n  /* Tools: one row per category that scrolls sideways */\n  .tools-groups {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 18px;\n  }\n\n  .tools-group-logos {\n    flex-wrap: nowrap;\n    gap: 8px;\n    margin-right: -20px;\n    padding: 0 20px 4px 0;\n    overflow-x: auto;\n    scroll-snap-type: x proximity;\n    scrollbar-width: none;\n  }\n\n  .tools-group-logos::-webkit-scrollbar {\n    display: none;\n  }\n\n  .tools-group-logos img {\n    width: 60px;\n    height: 60px;\n    flex: none;\n    scroll-snap-align: start;\n  }\n\n  /* Services: number on the left, title and text beside it */\n  .services-list {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .services-list li,\n  .services-list li + li,\n  .services-list li:nth-child(odd),\n  .services-list li:nth-child(n + 3) {\n    display: grid;\n    grid-template-columns: 46px minmax(0, 1fr);\n    column-gap: 12px;\n    padding: 14px 0;\n  }\n\n  .services-list li::before {\n    display: none;\n  }\n\n  .services-list .svc-no {\n    grid-row: span 2;\n    margin: 0;\n    font-size: 1.7rem;\n  }\n\n  .services-list h3 {\n    margin: 0 0 4px;\n  }\n\n  .services-list p {\n    margin: 0;\n  }\n\n  /* Recent Work: a swipeable row */\n  .bento-work-plain .bento-work-grid {\n    display: flex;\n    gap: 12px;\n    margin: 0 -12px;\n    padding: 4px 12px 12px;\n    overflow-x: auto;\n    scroll-snap-type: x mandatory;\n    scrollbar-width: none;\n  }\n\n  .bento-work-plain .bento-work-grid::-webkit-scrollbar {\n    display: none;\n  }\n\n  .bento-work-plain .bento-work-item {\n    flex: 0 0 82%;\n    scroll-snap-align: start;\n  }\n\n  /* Summary cards: no forced height */\n  .sum-card {\n    min-height: 0;\n    padding: 20px;\n  }\n\n  /* Tighter card padding everywhere */\n  .bento-card {\n    padding: 18px 16px;\n  }\n\n  .home-hero,\n  .cd-rich,\n  .gm-card,\n  .bento-photo {\n    padding: 0;\n  }\n\n  /* Dock: pull the end items in so the notch can reach them */\n  .dock-items {\n    padding: 0 8px;\n  }\n}\n\n@media (max-width: 600px) {\n  /* About: photo card no taller than it needs to be */\n  .bento-photo img {\n    max-height: 340px;\n  }\n\n  /* Swipe rows: About featured work, How I Work, Portfolio websites */\n  .bento-work:not(.bento-work-plain) .bento-work-grid,\n  .how-grid,\n  .pf-group[data-category=\"websites\"] .pf-site-grid {\n    display: flex;\n    gap: 12px;\n    margin: 0 -16px;\n    padding: 4px 16px 12px;\n    overflow-x: auto;\n    scroll-snap-type: x mandatory;\n    scrollbar-width: none;\n  }\n\n  .bento-work:not(.bento-work-plain) .bento-work-grid::-webkit-scrollbar,\n  .how-grid::-webkit-scrollbar,\n  .pf-site-grid::-webkit-scrollbar,\n  .pf-filters::-webkit-scrollbar {\n    display: none;\n  }\n\n  .bento-work:not(.bento-work-plain) .bento-work-item,\n  .how-item,\n  .pf-group[data-category=\"websites\"] .pf-site {\n    flex: 0 0 84%;\n    scroll-snap-align: start;\n  }\n\n  /* Portfolio designs: two tiles per row */\n  .pf-art-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 10px;\n  }\n\n  .pf-art {\n    padding: 8px 8px 10px;\n    gap: 8px;\n  }\n\n  .pf-art figcaption strong {\n    font-size: 0.82rem;\n  }\n\n  /* Portfolio headers: smaller, no count badge (the filter chips show it) */\n  .pf-group-head {\n    gap: 12px;\n    margin-bottom: 16px;\n  }\n\n  .pf-group-icon {\n    width: 40px;\n    height: 40px;\n  }\n\n  .pf-group-head h2 {\n    font-size: 1.1rem;\n  }\n\n  .pf-group-count {\n    display: none;\n  }\n\n  .pf-filters {\n    scrollbar-width: none;\n  }\n}\n\n@media (max-width: 600px) {\n  /* Contact tiles: a little tighter so the email fits, breaking at the @ */\n  .cd-tiles {\n    padding: 16px 14px 4px;\n  }\n\n  .cd-tile {\n    gap: 10px;\n    padding: 12px;\n  }\n\n  .cd-tile-ic {\n    width: 36px;\n    height: 36px;\n  }\n\n  .cd-tile-text a,\n  .cd-tile-text span {\n    font-size: 0.84rem;\n    overflow-wrap: normal;\n  }\n\n  .cd-clock {\n    padding: 14px 14px 18px;\n  }\n}\n\n/* Hero stats: dark forest card, icon + number + label per row */\n.home-hero .hero-stats {\n  gap: 10px;\n  padding: 14px;\n  border-radius: 20px;\n  background:\n    radial-gradient(120% 90% at 100% 0%, rgba(201, 162, 74, 0.22), transparent 60%),\n    var(--brand);\n  box-shadow: 0 18px 40px -22px rgba(19, 42, 33, 0.55);\n}\n\n.home-hero .hero-stats li {\n  display: grid;\n  grid-template-columns: 42px minmax(0, 1fr);\n  grid-template-rows: auto auto;\n  column-gap: 12px;\n  row-gap: 2px;\n  align-items: center;\n  padding: 10px 12px;\n  border-radius: 14px;\n  background: rgba(247, 245, 239, 0.06);\n}\n\n.home-hero .hs-ic {\n  grid-row: 1 / span 2;\n  display: grid;\n  place-items: center;\n  width: 42px;\n  height: 42px;\n  border-radius: 12px;\n  background: rgba(201, 162, 74, 0.18);\n}\n\n.home-hero .hs-ic svg {\n  width: 20px;\n  height: 20px;\n  fill: none;\n  stroke: var(--spark);\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.home-hero .hero-stats strong {\n  min-width: 0;\n  color: var(--paper);\n  font-size: 1.55rem;\n  line-height: 1;\n}\n\n.home-hero .hero-stats li > span:not(.hs-ic) {\n  color: rgba(247, 245, 239, 0.7);\n  font-size: 0.68rem;\n}\n\n@media (max-width: 1280px) {\n  .home-hero .hero-stats {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    padding: 10px;\n  }\n}\n\n@media (max-width: 600px) {\n  .home-hero .hero-stats {\n    gap: 8px;\n    padding: 8px;\n  }\n\n  .home-hero .hero-stats li {\n    grid-template-columns: minmax(0, 1fr);\n    justify-items: center;\n    row-gap: 6px;\n    padding: 12px 6px;\n    text-align: center;\n  }\n\n  .home-hero .hs-ic {\n    grid-row: auto;\n    width: 34px;\n    height: 34px;\n  }\n\n  .home-hero .hero-stats li > span:not(.hs-ic) {\n    font-size: 0.6rem;\n  }\n}\n\n/* Sidebar footer pinned to the bottom, logos centered on cream discs */\n.side-foot {\n  margin-top: auto;\n  padding-top: 20px;\n}\n\n.side-foot-row {\n  justify-content: center;\n}\n\n.side-socials {\n  gap: 10px;\n}\n\n.side-socials a {\n  background: #f7f5ef;\n}\n\n.side-socials a:hover {\n  background: #e8dfc4;\n}\n\n.side-socials a {\n  width: 44px;\n  height: 44px;\n}\n\n.side-socials img {\n  width: 24px;\n  height: 24px;\n}\n\n/* Top Skills: logo disc at the start of each chip */\n.skill-chips-logo li {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 5px 14px 5px 5px;\n}\n\n.chip-ic {\n  display: grid;\n  place-items: center;\n  width: 26px;\n  height: 26px;\n  border-radius: 999px;\n  background: var(--paper);\n}\n\n.chip-ic img {\n  width: 17px;\n  height: 17px;\n  object-fit: contain;\n}\n\n.chip-ic-svg svg {\n  width: 15px;\n  height: 15px;\n  fill: none;\n  stroke: var(--brand);\n  stroke-width: 2;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n/* Mobile topbar: same cream logo discs as the sidebar */\n.topbar-socials {\n  gap: 6px;\n}\n\n.topbar-socials a {\n  width: 34px;\n  height: 34px;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  background: #f7f5ef;\n}\n\n.topbar-socials a:hover {\n  background: #e8dfc4;\n}\n\n.topbar-socials img {\n  width: 19px;\n  height: 19px;\n}\n\n@media (max-width: 600px) {\n  .topbar-socials {\n    display: flex;\n  }\n}\n\n.chip-ic {\n  width: 28px;\n  height: 28px;\n}\n\n.chip-ic img {\n  width: 20px;\n  height: 20px;\n}\n\n/* ===========================================================\n   HOME: Test Scores (two stat tiles, then the DISC profile)\n   =========================================================== */\n.ts {\n  display: grid;\n  gap: 10px;\n}\n\n.ts-tiles {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.ts-tile {\n  display: grid;\n  gap: 4px;\n  padding: 14px;\n  border-radius: 16px;\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.ts-ic {\n  display: grid;\n  place-items: center;\n  width: 32px;\n  height: 32px;\n  margin-bottom: 6px;\n  border-radius: 10px;\n  background: rgba(201, 162, 74, 0.18);\n}\n\n.ts-ic svg {\n  width: 17px;\n  height: 17px;\n  fill: none;\n  stroke: var(--spark);\n  stroke-width: 1.8;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.ts-tile strong {\n  font-size: 1.9rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1;\n}\n\n.ts-tile small {\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.74rem;\n  line-height: 1.35;\n}\n\n.ts-disc {\n  padding: 16px;\n  border-radius: 16px;\n  background: var(--surface-2);\n}\n\n.ts-disc h3 {\n  margin: 0 0 12px;\n  color: var(--text);\n  font-size: 0.78rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.ts-bars {\n  display: grid;\n  gap: 10px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.ts-bars li {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 5px 10px;\n  align-items: center;\n}\n\n.ts-bars span {\n  color: var(--muted);\n  font-size: 0.82rem;\n}\n\n.ts-bars strong {\n  color: var(--text);\n  font-size: 0.82rem;\n  font-weight: 700;\n}\n\n.ts-bars b {\n  grid-column: 1 / -1;\n  position: relative;\n  height: 8px;\n  border-radius: 999px;\n  background: var(--paper);\n  overflow: hidden;\n}\n\n.ts-bars b::after {\n  content: \"\";\n  position: absolute;\n  inset: 0 auto 0 0;\n  width: var(--value);\n  border-radius: inherit;\n  background: var(--c);\n}\n\n/* Phones: How I Work stacks as compact steps; other swipe rows keep their side padding when snapping */\n@media (max-width: 600px) {\n  .bento-work:not(.bento-work-plain) .bento-work-grid,\n  .pf-group[data-category=\"websites\"] .pf-site-grid {\n    scroll-padding-inline: 16px;\n  }\n\n  .how-grid {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr);\n    gap: 10px;\n    margin: 0;\n    padding: 0;\n    overflow: visible;\n    scroll-snap-type: none;\n  }\n\n  .how-item {\n    flex: none;\n    gap: 8px;\n    padding: 16px;\n  }\n\n  .how-item .how-num {\n    font-size: 1.6rem;\n  }\n\n  .how-item .how-icon {\n    width: 38px;\n    height: 38px;\n  }\n\n  .how-item h3 {\n    font-size: 1rem;\n  }\n\n  .how-item p {\n    font-size: 0.88rem;\n    line-height: 1.55;\n  }\n}\n\n/* Travel coverflow: side photos stay inside the card instead of widening the page */\n.bento-travel {\n  overflow: hidden;\n}\n\n/* Hero stats under the text (tablet and phone): full width, icon above the number */\n@media (max-width: 1280px) {\n  .home-hero .hero-stats {\n    justify-self: stretch;\n    width: 100%;\n    max-width: 560px;\n    box-sizing: border-box;\n  }\n}\n\n@media (max-width: 800px) {\n  .home-hero .hero-stats {\n    gap: 8px;\n    padding: 8px;\n    max-width: none;\n  }\n\n  .home-hero .hero-stats li {\n    grid-template-columns: minmax(0, 1fr);\n    justify-items: center;\n    row-gap: 6px;\n    padding: 12px 6px;\n    text-align: center;\n  }\n\n  .home-hero .hs-ic {\n    grid-row: auto;\n    width: 34px;\n    height: 34px;\n  }\n\n  .home-hero .hero-stats li > span:not(.hs-ic) {\n    font-size: 0.6rem;\n  }\n}\n\n/* Top Skills: small group labels for Skills and Tools */\n.chip-group-label {\n  margin: 0 0 8px;\n  color: var(--muted);\n  font-size: 0.7rem;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n.chip-group-label + .skill-chips {\n  margin-bottom: 18px;\n}\n\n.skill-chips-logo:last-child {\n  margin-bottom: 0;\n}\n\n/* About: Skills & Tools chips match the home card */\n.bento-skills .skill-chips-logo li {\n  padding: 5px 14px 5px 5px;\n  font-size: 0.86rem;\n}\n\n/* ===========================================================\n   CASE STUDIES\n   =========================================================== */\n.cs-case {\n  display: grid;\n  gap: 22px;\n  padding: 28px;\n  scroll-margin-top: 96px;\n}\n\n.cs-head {\n  display: flex;\n  align-items: flex-start;\n  gap: 18px;\n}\n\n.cs-num {\n  flex: none;\n  display: grid;\n  place-items: center;\n  width: 52px;\n  height: 52px;\n  border-radius: 16px;\n  background: var(--gradient);\n  color: var(--spark);\n  font-size: 1.05rem;\n  font-weight: 800;\n}\n\n.cs-meta {\n  margin: 0 0 4px;\n  color: var(--spark-ink);\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.cs-head h2 {\n  margin: 0 0 6px;\n  color: var(--text);\n  font-size: 1.55rem;\n  font-weight: 800;\n  letter-spacing: -0.01em;\n}\n\n.cs-headline {\n  margin: 0;\n  max-width: 62ch;\n  color: var(--muted);\n  font-size: 1rem;\n  line-height: 1.55;\n}\n\n/* Key numbers: before value small and faded, after value large */\n.cs-metrics {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 10px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.cs-metrics li {\n  display: grid;\n  align-content: start;\n  gap: 6px;\n  padding: 16px;\n  border-radius: 16px;\n  background:\n    radial-gradient(120% 100% at 100% 0%, rgba(201, 162, 74, 0.2), transparent 60%),\n    var(--brand);\n}\n\n.cs-metrics strong {\n  color: var(--paper);\n  font-size: 1.6rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1.05;\n}\n\n.cs-metrics s {\n  color: rgba(247, 245, 239, 0.5);\n  font-size: 0.62em;\n  font-weight: 700;\n  text-decoration: none;\n}\n\n.cs-metrics s::after {\n  content: \" \\2192\";\n  color: var(--spark);\n}\n\n.cs-metrics span {\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.74rem;\n  line-height: 1.35;\n}\n\n.cs-cols {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.cs-block {\n  padding: 18px 20px;\n  border-radius: 16px;\n  background: var(--surface-2);\n}\n\n.cs-block h3 {\n  margin: 0 0 10px;\n  color: var(--text);\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n.cs-block ul {\n  display: grid;\n  gap: 8px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.cs-block li {\n  position: relative;\n  padding-left: 18px;\n  color: var(--text);\n  font-size: 0.92rem;\n  line-height: 1.5;\n}\n\n.cs-block li::before {\n  content: \"\";\n  position: absolute;\n  top: 0.55em;\n  left: 0;\n  width: 7px;\n  height: 7px;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n.cs-foot {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n}\n\n.cs-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.cs-tags li {\n  padding: 5px 12px;\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--muted);\n  font-size: 0.78rem;\n  font-weight: 600;\n}\n\n.cs-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.cs-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 11px 18px;\n  border-radius: 12px;\n  font-size: 0.9rem;\n  font-weight: 700;\n  text-decoration: none;\n  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;\n}\n\n.cs-btn-main {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.cs-btn-main:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 12px 24px -14px rgba(19, 42, 33, 0.7);\n}\n\n.cs-btn-alt {\n  background: var(--surface-2);\n  color: var(--text);\n}\n\n.cs-btn-alt:hover {\n  background: #e8dfc4;\n}\n\n.cs-jump .pf-filter {\n  text-decoration: none;\n}\n\n@media (max-width: 900px) {\n  .cs-metrics {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 700px) {\n  .cs-case {\n    gap: 18px;\n    padding: 20px 18px;\n  }\n\n  .cs-head {\n    gap: 14px;\n  }\n\n  .cs-num {\n    width: 42px;\n    height: 42px;\n    border-radius: 12px;\n    font-size: 0.92rem;\n  }\n\n  .cs-head h2 {\n    font-size: 1.3rem;\n  }\n\n  .cs-headline {\n    font-size: 0.92rem;\n  }\n\n  .cs-cols {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .cs-metrics strong {\n    font-size: 1.35rem;\n  }\n\n  .cs-actions,\n  .cs-btn {\n    width: 100%;\n  }\n\n  .cs-btn {\n    justify-content: center;\n  }\n}\n\n/* Case studies: book mockup beside the story, opens the PDF */\n.cs-cover {\n  display: block;\n  justify-self: center;\n  width: min(240px, 70%);\n  transition: transform 0.3s ease;\n}\n\n.cs-cover img {\n  display: block;\n  width: 100%;\n  height: auto;\n  filter: drop-shadow(0 18px 22px rgba(19, 42, 33, 0.22));\n}\n\n.cs-cover:hover {\n  transform: translateY(-6px) rotate(-1deg);\n}\n\n@media (min-width: 1100px) {\n  .cs-case {\n    grid-template-columns: minmax(0, 1fr) clamp(200px, 26%, 290px);\n    column-gap: 28px;\n  }\n\n  .cs-case > * {\n    grid-column: 1;\n  }\n\n  .cs-case > .cs-cover {\n    grid-column: 2;\n    grid-row: 1 / span 3;\n    align-self: center;\n    width: 100%;\n  }\n\n  .cs-case > .cs-foot {\n    grid-column: 1 / -1;\n  }\n}\n\n@media (max-width: 1280px) {\n  .cs-metrics {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 1099px) {\n  .cs-cover {\n    width: min(220px, 62%);\n    margin: -8px 0 -14px;\n  }\n}\n\n/* ===========================================================\n   HOME: Featured case studies (dark stage, books as the focal point)\n   =========================================================== */\n.fcs {\n  position: relative;\n  display: grid;\n  gap: 28px;\n  padding: 34px 34px 30px;\n  overflow: hidden;\n  background:\n    radial-gradient(70% 90% at 100% 0%, rgba(201, 162, 74, 0.2), transparent 60%),\n    radial-gradient(60% 80% at 0% 100%, rgba(247, 245, 239, 0.06), transparent 60%),\n    var(--brand-strong);\n  color: var(--paper);\n}\n\n.fcs-top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 18px 28px;\n}\n\n.fcs-eyebrow {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 10px;\n  color: var(--spark);\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.fcs-eyebrow::before {\n  content: \"\";\n  width: 7px;\n  height: 7px;\n  border-radius: 999px;\n  background: var(--spark);\n}\n\n.fcs-copy h2 {\n  margin: 0 0 8px;\n  max-width: 18ch;\n  color: var(--paper);\n  font-size: clamp(1.6rem, 2.6vw, 2.3rem);\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1.1;\n}\n\n.fcs-copy h2 span {\n  color: var(--spark);\n}\n\n.fcs-copy p:last-child {\n  margin: 0;\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.98rem;\n}\n\n.fcs-all {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 12px 20px;\n  border-radius: 12px;\n  background: var(--spark);\n  color: var(--brand-strong);\n  font-size: 0.92rem;\n  font-weight: 700;\n  text-decoration: none;\n  white-space: nowrap;\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.fcs-all:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 12px 24px -12px rgba(201, 162, 74, 0.8);\n}\n\n.fcs-books {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 14px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.fcs-book {\n  display: grid;\n  justify-items: center;\n  gap: 2px;\n  height: 100%;\n  padding: 10px 12px 18px;\n  border-radius: 18px;\n  background: rgba(247, 245, 239, 0.05);\n  color: var(--paper);\n  text-align: center;\n  text-decoration: none;\n  transition: background 0.25s ease, transform 0.25s ease;\n}\n\n.fcs-book:hover {\n  background: rgba(247, 245, 239, 0.1);\n  transform: translateY(-4px);\n}\n\n/* Soft pool of light under each book */\n.fcs-stage {\n  position: relative;\n  display: block;\n  width: 100%;\n  max-width: 230px;\n  margin-bottom: 6px;\n}\n\n.fcs-stage::after {\n  content: \"\";\n  position: absolute;\n  left: 18%;\n  right: 18%;\n  bottom: 9%;\n  height: 12%;\n  border-radius: 50%;\n  background: rgba(0, 0, 0, 0.45);\n  filter: blur(14px);\n  z-index: 0;\n}\n\n.fcs-stage img {\n  position: relative;\n  z-index: 1;\n  display: block;\n  width: 100%;\n  height: auto;\n  transition: transform 0.35s ease;\n}\n\n.fcs-book:hover .fcs-stage img {\n  transform: translateY(-6px) rotate(-1.5deg);\n}\n\n.fcs-num {\n  color: var(--spark);\n  font-size: 1.55rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1.1;\n}\n\n.fcs-num i {\n  color: rgba(247, 245, 239, 0.45);\n  font-size: 0.7em;\n  font-style: normal;\n}\n\n.fcs-label {\n  color: rgba(247, 245, 239, 0.72);\n  font-size: 0.78rem;\n}\n\n.fcs-client {\n  margin-top: 8px;\n  color: var(--paper);\n  font-size: 0.9rem;\n  font-weight: 700;\n}\n\n/* Tablet: two books per row */\n@media (max-width: 1100px) {\n  .fcs-books {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .fcs-stage {\n    max-width: 200px;\n  }\n}\n\n/* Phone: a swipeable shelf so the section stays short */\n@media (max-width: 600px) {\n  .fcs {\n    gap: 20px;\n    padding: 24px 18px 20px;\n  }\n\n  .fcs-all {\n    width: 100%;\n    justify-content: center;\n  }\n\n  .fcs-books {\n    display: flex;\n    gap: 10px;\n    margin: 0 -18px;\n    padding: 0 18px 6px;\n    overflow-x: auto;\n    scroll-snap-type: x mandatory;\n    scroll-padding-inline: 18px;\n    scrollbar-width: none;\n  }\n\n  .fcs-books::-webkit-scrollbar {\n    display: none;\n  }\n\n  .fcs-books li {\n    flex: 0 0 62%;\n    scroll-snap-align: start;\n  }\n\n  .fcs-num {\n    font-size: 1.3rem;\n  }\n}\n\n/* Featured case studies: refinements */\n.fcs-copy h2 {\n  max-width: 24ch;\n}\n\n@media (max-width: 1100px) {\n  .fcs-books {\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    gap: 10px;\n  }\n\n  .fcs-book {\n    padding: 8px 6px 14px;\n  }\n\n  .fcs-num {\n    font-size: 1.2rem;\n  }\n\n  .fcs-label {\n    font-size: 0.7rem;\n  }\n\n  .fcs-client {\n    font-size: 0.8rem;\n  }\n}\n\n@media (max-width: 700px) {\n  .fcs {\n    gap: 20px;\n    padding: 24px 18px 20px;\n  }\n\n  .fcs-all {\n    width: 100%;\n    justify-content: center;\n  }\n\n  .fcs-books {\n    display: flex;\n    gap: 10px;\n    margin: 0 -18px;\n    padding: 0 18px 6px;\n    overflow-x: auto;\n    scroll-snap-type: x mandatory;\n    scroll-padding-inline: 18px;\n    scrollbar-width: none;\n  }\n\n  .fcs-books li {\n    flex: 0 0 62%;\n    scroll-snap-align: start;\n  }\n\n  .fcs-num {\n    font-size: 1.35rem;\n  }\n\n  .fcs-label {\n    font-size: 0.76rem;\n  }\n\n  .fcs-client {\n    font-size: 0.88rem;\n  }\n}\n\n/* Keep numbers level across tiles; client name sits at the bottom */\n.fcs-book {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\n.fcs-client {\n  margin-top: auto;\n  padding-top: 8px;\n}\n\n/* Featured case studies: light version, books carry the color */\n.fcs {\n  background:\n    radial-gradient(60% 80% at 100% 0%, rgba(201, 162, 74, 0.14), transparent 60%),\n    var(--paper);\n  color: var(--text);\n}\n\n.fcs-eyebrow {\n  color: var(--spark-ink);\n}\n\n.fcs-eyebrow::before {\n  background: var(--spark);\n}\n\n.fcs-copy h2 {\n  color: var(--text);\n}\n\n.fcs-copy h2 span {\n  color: var(--spark-ink);\n}\n\n.fcs-copy p:last-child {\n  color: var(--muted);\n}\n\n.fcs-all {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.fcs-all:hover {\n  box-shadow: 0 12px 24px -12px rgba(19, 42, 33, 0.6);\n}\n\n.fcs-book {\n  background: var(--surface-2);\n  color: var(--text);\n}\n\n.fcs-book:hover {\n  background: #e9e3d2;\n}\n\n.fcs-stage::after {\n  background: rgba(19, 42, 33, 0.35);\n}\n\n.fcs-num {\n  color: var(--brand);\n}\n\n.fcs-num i {\n  color: var(--spark);\n}\n\n.fcs-label {\n  color: var(--muted);\n}\n\n.fcs-client {\n  color: var(--text);\n}\n\n/* ===========================================================\n   Case study reader (on-site PDF viewer)\n   =========================================================== */\n.pdfv {\n  width: min(960px, calc(100vw - 32px));\n  height: calc(100dvh - 48px);\n  max-width: none;\n  max-height: none;\n  margin: auto;\n  padding: 0;\n  border: 0;\n  border-radius: 20px;\n  background: var(--surface-2);\n  color: var(--text);\n  overflow: hidden;\n  box-shadow: 0 30px 80px -20px rgba(19, 42, 33, 0.5);\n}\n\n.pdfv[open] {\n  display: flex;\n  flex-direction: column;\n  animation: pdfv-in 0.25s ease;\n}\n\n@keyframes pdfv-in {\n  from { opacity: 0; transform: translateY(12px) scale(0.98); }\n  to { opacity: 1; transform: none; }\n}\n\n.pdfv::backdrop {\n  background: rgba(19, 42, 33, 0.72);\n  backdrop-filter: blur(4px);\n}\n\nhtml.pdfv-open {\n  overflow: hidden;\n}\n\n.pdfv-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 14px 16px 14px 22px;\n  background: var(--brand-strong);\n  color: var(--paper);\n}\n\n.pdfv-title {\n  display: grid;\n  min-width: 0;\n}\n\n.pdfv-title small {\n  color: var(--spark);\n  font-size: 0.68rem;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.pdfv-title strong {\n  overflow: hidden;\n  font-size: 1.02rem;\n  font-weight: 700;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.pdfv-actions {\n  display: flex;\n  flex: none;\n  gap: 8px;\n}\n\n.pdfv-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  height: 40px;\n  min-width: 40px;\n  padding: 0 14px;\n  border: 0;\n  border-radius: 10px;\n  background: rgba(247, 245, 239, 0.1);\n  color: var(--paper);\n  font: inherit;\n  font-size: 0.86rem;\n  font-weight: 700;\n  text-decoration: none;\n  cursor: pointer;\n  transition: background 0.2s ease;\n}\n\n.pdfv-btn:hover {\n  background: rgba(247, 245, 239, 0.2);\n}\n\n.pdfv-close {\n  padding: 0;\n}\n\n.pdfv-btn svg {\n  width: 18px;\n  height: 18px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 2;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n.pdfv-body {\n  flex: 1;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 22px;\n}\n\n.pdfv-pages {\n  display: grid;\n  gap: 16px;\n  max-width: 820px;\n  margin: 0 auto;\n}\n\n.pdfv-pages canvas {\n  display: block;\n  width: 100%;\n  height: auto;\n  border-radius: 8px;\n  background: #fff;\n  box-shadow: 0 10px 30px -14px rgba(19, 42, 33, 0.35);\n}\n\n@media (max-width: 600px) {\n  .pdfv {\n    width: 100vw;\n    height: 100dvh;\n    border-radius: 0;\n  }\n\n  .pdfv-bar {\n    padding: 10px 10px 10px 16px;\n  }\n\n  .pdfv-body {\n    padding: 12px 10px 24px;\n  }\n\n  .pdfv-pages {\n    gap: 10px;\n  }\n}\n\n/* Case studies: book on the left, story on the right */\n@media (min-width: 1100px) {\n  .cs-case {\n    grid-template-columns: clamp(200px, 24%, 280px) minmax(0, 1fr);\n  }\n\n  .cs-case > * {\n    grid-column: 2;\n  }\n\n  .cs-case > .cs-cover {\n    grid-column: 1;\n    grid-row: 1 / span 4;\n  }\n\n  .cs-case > .cs-foot {\n    grid-column: 2;\n  }\n}\n\n/* Case studies: book with its Read / Download buttons underneath */\n.cs-side {\n  display: grid;\n  justify-items: center;\n  align-content: center;\n  gap: 16px;\n}\n\n.cs-side .cs-cover {\n  width: min(240px, 70%);\n}\n\n.cs-side .cs-actions {\n  display: grid;\n  gap: 8px;\n  width: min(260px, 100%);\n}\n\n.cs-side .cs-btn {\n  justify-content: center;\n  width: 100%;\n}\n\n@media (min-width: 1100px) {\n  .cs-case > .cs-side {\n    grid-column: 1;\n    grid-row: 1 / span 4;\n  }\n\n  .cs-side .cs-cover {\n    width: 100%;\n  }\n}\n\n@media (max-width: 1099px) {\n  .cs-side .cs-cover {\n    margin: -8px 0 -14px;\n  }\n}\n\n/* ===========================================================\n   HOME: bigger featured books (the PNGs carry empty margins,\n   so the image is enlarged past its tile edge)\n   =========================================================== */\n.fcs-stage {\n  max-width: none;\n  margin-bottom: 2px;\n}\n\n.fcs-stage img {\n  width: 118%;\n  max-width: none;\n  margin: -6% -9% -5%;\n}\n\n.fcs-book {\n  padding: 6px 8px 16px;\n}\n\n@media (max-width: 700px) {\n  .fcs-books li {\n    flex-basis: 70%;\n  }\n}\n\n.fcs-stage img {\n  margin-bottom: -1%;\n}\n\n.fcs-stage {\n  margin-bottom: 8px;\n}\n\n/* Reader pages are watermarked images; keep them from being selected or dragged */\n.pdfv-pages img {\n  display: block;\n  width: 100%;\n  height: auto;\n  border-radius: 8px;\n  background: #fff;\n  box-shadow: 0 10px 30px -14px rgba(19, 42, 33, 0.35);\n  user-select: none;\n  -webkit-user-drag: none;\n  -webkit-touch-callout: none;\n}\n\n/* Case study tool tags: logo disc + name, same as the Top Skills chips */\n.cs-tags li {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 5px 14px 5px 5px;\n  color: var(--text);\n  font-size: 0.82rem;\n}\n\n/* 404 page */\n.nf {\n  display: grid;\n  justify-items: center;\n  gap: 12px;\n  padding: 64px 28px;\n  text-align: center;\n  background:\n    radial-gradient(60% 80% at 50% 0%, rgba(201, 162, 74, 0.16), transparent 65%),\n    var(--paper);\n}\n\n.nf-code {\n  margin: 0;\n  color: var(--spark-ink);\n  font-size: clamp(4rem, 12vw, 7rem);\n  font-weight: 800;\n  letter-spacing: -0.04em;\n  line-height: 1;\n}\n\n.nf h1 {\n  margin: 0;\n  color: var(--text);\n  font-size: clamp(1.4rem, 3vw, 2rem);\n  font-weight: 800;\n}\n\n.nf-text {\n  max-width: 44ch;\n  margin: 0 0 8px;\n  color: var(--muted);\n}\n\n.nf-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 8px;\n}\n\n/* ===========================================================\n   HOME: FAQ (intro on the left, expandable answers on the right)\n   =========================================================== */\n.faq {\n  display: grid;\n  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.4fr);\n  gap: 32px;\n  padding: 34px;\n}\n\n.faq-intro {\n  align-self: start;\n  display: grid;\n  justify-items: start;\n  gap: 10px;\n}\n\n.faq-intro .fcs-eyebrow {\n  margin: 0;\n  color: var(--spark-ink);\n}\n\n.faq-intro h2 {\n  margin: 0;\n  color: var(--text);\n  font-size: clamp(1.5rem, 2.4vw, 2rem);\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  line-height: 1.15;\n}\n\n.faq-intro p:not(.fcs-eyebrow) {\n  margin: 0 0 8px;\n  color: var(--muted);\n}\n\n.faq-intro .fcs-all {\n  background: var(--brand);\n  color: var(--paper);\n}\n\n.faq-list {\n  display: grid;\n  gap: 10px;\n}\n\n.faq-item {\n  border-radius: 16px;\n  background: var(--surface-2);\n  transition: background 0.2s ease;\n}\n\n.faq-item[open] {\n  background: #ebe5d3;\n}\n\n.faq-item summary {\n  position: relative;\n  padding: 16px 56px 16px 20px;\n  color: var(--text);\n  font-size: 0.98rem;\n  font-weight: 700;\n  list-style: none;\n  cursor: pointer;\n}\n\n.faq-item summary::-webkit-details-marker {\n  display: none;\n}\n\n/* Plus that turns into a minus */\n.faq-item summary::before,\n.faq-item summary::after {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  right: 22px;\n  width: 14px;\n  height: 2px;\n  border-radius: 2px;\n  background: var(--spark-ink);\n  transition: transform 0.25s ease;\n}\n\n.faq-item summary::after {\n  transform: rotate(90deg);\n}\n\n.faq-item[open] summary::after {\n  transform: rotate(0deg);\n}\n\n.faq-item summary:focus-visible {\n  outline: 2px solid var(--spark);\n  outline-offset: 2px;\n  border-radius: 16px;\n}\n\n.faq-item p {\n  margin: 0;\n  padding: 0 20px 18px;\n  color: var(--muted);\n  font-size: 0.94rem;\n  line-height: 1.6;\n}\n\n@media (max-width: 900px) {\n  .faq {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 20px;\n  }\n}\n\n@media (max-width: 600px) {\n  .faq {\n    padding: 22px 18px;\n  }\n\n  .faq-intro .fcs-all {\n    width: 100%;\n    justify-content: center;\n  }\n\n  .faq-item summary {\n    padding: 14px 50px 14px 16px;\n    font-size: 0.94rem;\n  }\n\n  .faq-item p {\n    padding: 0 16px 16px;\n  }\n}\n\n/* About: \"Tools I Use\" now runs the full tool list, so it moves slower */\n.bento-tool-track {\n  animation-duration: 105s;\n}\n\n/* Home tools panel: SEO group icon, drawn to match the glowing folder icons */\n.tools-seo-ic {\n  width: 32px;\n  height: 32px;\n  flex: none;\n  fill: none;\n  stroke: #3ee0a8;\n  stroke-width: 2.2;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  filter: drop-shadow(0 0 3px rgba(62, 224, 168, 0.55));\n}\n\n/* Home tools panel: every logo sits in the same size tile, three per row.\n   The Tiles images are pre-trimmed and scaled to equal visual weight. */\n.tools-group-logos {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.tools-group-logos img {\n  width: 100%;\n  height: auto;\n  aspect-ratio: 3 / 2;\n  padding: 2px;\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  background: var(--bg);\n  object-fit: contain;\n  transition: transform 0.22s ease, border-color 0.22s ease;\n}\n\n.tools-group-logos img:hover {\n  transform: translateY(-3px);\n  border-color: var(--spark);\n}\n\n@media (max-width: 600px) {\n  .tools-group-logos {\n    gap: 8px;\n    margin-right: 0;\n    padding: 0;\n    overflow: visible;\n  }\n\n  .tools-group-logos img {\n    width: 100%;\n    height: auto;\n  }\n}\n"});
